add({rank:0,type:'scene',cat:'Scherzfrage',title:'Forelle blau',prompt:'Welche „Farbe“ braucht man für Forelle blau?',scenes:[['Blaue Füllertinte','',0],['Blaue Lackfarbe','',0],['Keine Farbe – Säure, z. B. Essig im Sud, unterstützt die Blaufärbung','',1],['Lebensmittelfarbe Blau','',0]],explain:'Für Forelle blau wird keine blaue Farbe verwendet. Die typische Blaufärbung hängt mit der Schleimschicht frischer Forellen und Säure zusammen.',hint:'Der Farbtopf darf im Büro bleiben.',knowledge:{title:'Warum wird die Forelle blau?',text:'Die Schleimschicht einer sehr frischen Forelle reagiert beim Garen in einem säurehaltigen Sud und kann dadurch blau erscheinen. Die Schleimschicht sollte dafür möglichst intakt bleiben.',facts:['Keine Lebensmittelfarbe','Säurehaltiger Sud','Frische & intakte Schleimschicht']}});
add({rank:1,type:'scene',cat:'Scherzfrage',title:'Blanchieren',prompt:'Was braucht man zum fachgerechten Blanchieren am wenigsten?',scenes:[['Kochendes Wasser oder Dampf','',0],['Anschließendes Abschrecken je nach Produkt/Zweck','',0],['Bleichmittel aus der Waschküche','',1],['Geeignetes Gargut','',0]],explain:'Blanchieren hat mit Bleichmittel natürlich nichts zu tun. Es ist ein kurzes Erhitzen, häufig in kochendem Wasser oder Dampf.',hint:'Ein Küchenfachbegriff ist kein Waschprogramm.',knowledge:{title:'Fachbegriff · Blanchieren',text:'Blanchieren bedeutet kurzes Erhitzen, meist in kochendem Wasser oder Dampf. Je nach Zweck wird anschließend rasch gekühlt.',facts:['Kurzzeiterhitzung','Wasser oder Dampf','Häufig anschließend kühlen']}});
add({rank:2,type:'scene',cat:'Warenkunde',title:'Tomate',prompt:'Welche Lagerung ist für aromatische, noch nicht überreife Tomaten meist sinnvoll?',scenes:[['Kühl, aber nicht unnötig kalt; häufig besser außerhalb des Kühlschranks','',1],['Grundsätzlich tiefgefrieren, solange sie frisch sind','',0],['Immer direkt neben stark ethylenempfindlichem Gemüse lagern','',0],['In Wasser lagern','',0]],explain:'Tomaten verlieren bei sehr kalter Lagerung häufig Aroma und Textur; für kurze Lagerung ist ein geeigneter kühler Platz außerhalb des Kühlschranks oft besser.',hint:'Aroma und Kälte vertragen sich bei Tomaten nicht immer gut.',knowledge:{title:'Warenkunde · Tomate',text:'Tomaten stammen botanisch aus Amerika und sind heute weltweit bedeutend. In der Küche reichen die Anwendungen von Salat über Sauce bis Schmoren und Trocknen.',facts:['Verwendung: roh · Sauce · Schmoren','Deutsche Saison: vor allem Sommer','Nicht unnötig kalt lagern']}});
