add({rank:0,type:'scene',section:'Materialkunde',cat:'Kochgeschirr',title:'Der Kochtopf',photo:'assets/real/cooking_pots.jpg',prompt:'Welches Arbeitsgerät ist für größere Mengen Wasser, Brühe oder Suppe am passendsten?',scenes:[['Hoher Kochtopf','🍲',1],['Flache Crêpepfanne','🍳',0],['Tortenring','⭕',0],['Wetzstahl','🗡️',0]],explain:'Ein hoher Kochtopf eignet sich für größere Flüssigkeitsmengen und viele Kochprozesse.',hint:'Gesucht ist ein Gefäß mit ausreichend Volumen und hohen Seiten.',knowledge:{title:'Materialkunde · Kochtopf',text:'Kochtöpfe gibt es u. a. aus Edelstahl, Aluminium-Verbundmaterial oder Gusseisen. Hohe Töpfe sind für Flüssigkeiten, Fonds, Suppen und größere Kochmengen besonders praktisch.',facts:['Einsatz: kochen · blanchieren · Suppen/Fonds','Wichtig: passender Durchmesser zur Kochzone','Deckel reduziert Wärme- und Flüssigkeitsverlust']}});
add({rank:0,type:'scene',section:'Materialkunde',cat:'Handwerkzeuge',title:'Schneebesen',photo:'assets/real/whisk.jpg',prompt:'Wofür ist ein Schneebesen besonders geeignet?',scenes:[['Flüssigkeiten verrühren und Luft einarbeiten','🥄',1],['Knochen zersägen','🪚',0],['Brot in Scheiben schneiden','🔪',0],['Kartoffeln schälen','🥔',0]],explain:'Der Schneebesen dient zum Verrühren, Aufschlagen und Emulgieren.',hint:'Denke an Sahne, Eiweiß, Saucen und Emulsionen.',knowledge:{title:'Materialkunde · Schneebesen',text:'Schneebesen bestehen häufig aus Edelstahl. Viele dünne Drähte vergrößern die Kontaktfläche und helfen, Flüssigkeiten zu mischen oder Luft einzuarbeiten.',facts:['Einsatz: Sahne · Eiweiß · Saucen','Material häufig: Edelstahl','Nicht mit scharfkantigen Werkzeugen verwechseln']}});
add({rank:0,type:'scene',section:'Materialkunde',cat:'Messer',title:'Brotmesser / Sägemesser',photo:'assets/real/kitchen_knives.jpg',prompt:'Welches Messer ist für Brot mit kräftiger Kruste besonders geeignet?',scenes:[['Sägemesser mit Wellenschliff','🔪',1],['Ausbeinmesser mit schmaler glatter Klinge','🔪',0],['Spickmesser','🔪',0],['Wetzstahl','🗡️',0]],explain:'Ein Sägemesser mit Wellenschliff schneidet Krusten sauber, ohne weiche Brote stark zusammenzudrücken.',hint:'Gesucht ist die gezahnte bzw. gewellte Schneide.',knowledge:{title:'Materialkunde · Sägemesser',text:'Der Wellenschliff greift harte Krusten gut und eignet sich besonders für Brot, Brötchen und manche empfindlichen Lebensmittel mit fester Außenhaut.',facts:['Kennzeichen: Wellenschliff','Typisch: Brot und Backwaren','Nicht mit Wetzstahl verwechseln']}});
add({rank:1,type:'scene',section:'Materialkunde',cat:'Messer',title:'Officemesser',prompt:'Welche Aufgabe passt am besten zu einem Officemesser?',scenes:[['Kleine Putz-, Schneid- und Schälarbeiten an Obst und Gemüse','🔪',1],['Große Knochen zerhacken','🪓',0],['20 Liter Suppe umrühren','🥄',0],['Brotkrusten mit Wellenschliff schneiden','🥖',0]],explain:'Das Officemesser ist ein kleines, handliches Universalmesser für feine Vorbereitungsarbeiten.',hint:'Klein, handlich und für Detailarbeiten.',knowledge:{title:'Materialkunde · Officemesser',text:'Das Officemesser besitzt eine kurze Klinge und wird für kleine Schneid-, Putz- und Schälarbeiten verwendet.',facts:['Einsatz: Obst · Gemüse · Garnituren','Kurze, handliche Klinge','Gut für präzise Detailarbeiten']}});
add({rank:1,type:'scene',section:'Materialkunde',cat:'Messer',title:'Spickmesser',prompt:'Welche Beschreibung passt am besten zu einem klassischen Spickmesser?',scenes:[['Schmale, spitze Klinge für feine Einstiche und kleine präzise Schneidarbeiten','🔪',1],['Breite Klinge zum Hacken großer Knochen','🪓',0],['Gezahnte Klinge ausschließlich für Brot','🥖',0],['Stahlstab zum Aufrichten der Schneide','🗡️',0]],explain:'Das Spickmesser ist schmal und spitz und eignet sich für feine Einstiche und präzise kleinere Arbeiten.',hint:'Achte auf die schmale, spitze Form.',knowledge:{title:'Materialkunde · Spickmesser',text:'Traditionell wurde das Spickmesser unter anderem beim Spicken verwendet. Heute dient die schmale, spitze Klinge auch für feine Schneid- und Putzarbeiten.',facts:['Form: schmal und spitz','Einsatz: feine Einstiche und Detailarbeiten','Tradition: Spicken von Fleisch']}});
