add({rank:1,type:'scene',section:'Materialkunde',cat:'Messerpflege',title:'Wetzstahl',prompt:'Welche Hauptaufgabe hat ein Wetzstahl im Küchenalltag?',scenes:[['Die Schneidkante eines geeigneten Messers aufrichten und pflegen','🗡️',1],['Brot mit Wellenschliff sägen','🥖',0],['Knochen durchtrennen','🪚',0],['Gemüse blanchieren','🥕',0]],explain:'Ein Wetzstahl richtet die Schneidkante geeigneter Messer wieder aus und hilft, die Schärfe zwischen Schleifvorgängen zu erhalten.',hint:'Er ersetzt nicht jeden Schleifvorgang, pflegt aber die Schneide.',knowledge:{title:'Materialkunde · Wetzstahl',text:'Beim Wetzen wird vor allem die feine Schneidkante wieder ausgerichtet. Stumpf gewordene oder beschädigte Messer benötigen gegebenenfalls einen echten Schleifvorgang.',facts:['Pflege: Schneidkante ausrichten','Nicht identisch mit Schleifen','Nur für geeignete Klingen verwenden']}});
