add({rank:1,type:'scene',section:'Warenkunde',cat:'Gemüse',title:'Weißer und grüner Spargel',prompt:'Warum bleibt weißer Spargel hell?',scenes:[['Er wächst weitgehend lichtgeschützt in Erddämmen','🌱',1],['Er wird nach der Ernte weiß lackiert','🎨',0],['Er besteht aus einer anderen Pflanzenfamilie als grüner Spargel','🌿',0],['Er wird tiefgefroren angebaut','❄️',0]],explain:'Weißer Spargel wächst lichtgeschützt; ohne Licht wird kaum Chlorophyll gebildet.',hint:'Die Farbe hängt mit Licht und Chlorophyll zusammen.',knowledge:{title:'Warenkunde · Spargel',text:'Weißer Spargel wird in Dämmen weitgehend ohne Licht kultiviert, grüner Spargel wächst oberirdisch und bildet Chlorophyll. Beide werden als Gemüse, Beilage, Suppe oder Salat verwendet.',facts:['Deutschland: wichtiges Saisonprodukt im Frühjahr','Weiß: lichtgeschützt','Grün: oberirdisch, chlorophyllreich']}});
add({rank:1,type:'scene',section:'Warenkunde',cat:'Fleisch',title:'Filet',prompt:'Welche Aussage trifft auf Filet im Allgemeinen am ehesten zu?',scenes:[['Es ist ein besonders zartes, wenig beanspruchtes Muskelstück und eignet sich häufig zum Kurzbraten','🥩',1],['Es ist ein stark beanspruchtes, bindegewebsreiches Schmorstück','🍲',0],['Es bezeichnet grundsätzlich ein Stück mit hohem Knochenanteil','🦴',0],['Es eignet sich fachlich nur zum Auskochen für Brühen','🥣',0]],explain:'Filet stammt aus wenig beanspruchter Muskulatur und ist deshalb besonders zart. Je nach Tier wird es zu Medaillons, Mignon, Tournedos oder im Ganzen zu Filetbraten verarbeitet.',hint:'Gesucht ist das zarte Edelstück – nicht das kollagenreiche Schmorstück.',knowledge:{title:'Warenkunde · Filet',text:'Das Filet liegt innen entlang der Wirbelsäule und wird wenig beansprucht. Dadurch ist es besonders zart und für hochwertige Kurzbrat- oder Bratenzuschnitte geeignet.',facts:['zartes Edelstück','klassische Zuschnitte: Medaillon · Mignon · Tournedos','im Ganzen auch als Filetbraten']},knowledge:{title:'Warenkunde · Fleisch',text:'Muskeln, die im Tier weniger arbeiten, sind häufig zarter als stark beanspruchte Muskelpartien. Das beeinflusst die Wahl des Garverfahrens.',facts:['Filet: zart und kurzbratgeeignet','Stärker beanspruchte Stücke: mehr Bindegewebe','Garverfahren nach Stück wählen']}});
