add({rank:4,type:'scene',section:'Warenkunde',cat:'Gemüse',title:'Gemüse richtig lagern',prompt:'Welche Aussage ist für die Lagerplanung am sinnvollsten?',scenes:[['Nicht jedes Gemüse braucht dieselbe Temperatur und Luftfeuchte; produktspezifisch lagern','🥕',1],['Alle Gemüsearten grundsätzlich warm und trocken lagern','🌡️',0],['Blattgemüse neben Heizkörpern lagern','🔥',0],['Lagerbedingungen spielen bei Frischware keine Rolle','📦',0]],explain:'Temperatur, Luftfeuchte und Ethylenempfindlichkeit unterscheiden sich zwischen Gemüsearten deutlich.',hint:'Lagerung ist produktspezifisch.',knowledge:{title:'Warenkunde · Lagerung',text:'Blattgemüse, Wurzelgemüse, Tomaten und Zwiebelgewächse stellen unterschiedliche Anforderungen an Temperatur und Feuchtigkeit. Gute Lagerplanung reduziert Qualitätsverlust und Verderb.',facts:['Temperatur beachten','Feuchtigkeit beachten','Ethylen und Nachreifung berücksichtigen']}});
