add({profession:'Küche',rank:4,type:'scene',section:'Rechnen',cat:'Kalkulation',title:'Portionsmenge hochrechnen',prompt:'Ein Rezept ergibt 12 Portionen und benötigt 1,8 kg Kartoffeln. Wie viel brauchst du für 30 Portionen?',scenes:[['4,5 kg','🧮',1],['3,6 kg','🧮',0],['5,4 kg','🧮',0],['6,0 kg','🧮',0]],explain:'1,8 kg ÷ 12 = 0,15 kg je Portion. 0,15 × 30 = 4,5 kg.',hint:'Erst die Menge pro Portion bestimmen, dann mit 30 multiplizieren.',math:true,knowledge:{title:'Kalkulation · Hochrechnen',text:'Beim Hochrechnen bleibt das Verhältnis der Rezeptmengen gleich. In der Praxis müssen Rundung, Gebindegrößen und Ausbeute zusätzlich berücksichtigt werden.',facts:['Grundmenge ÷ Portionen','mit Zielportionen multiplizieren','Praxisreserve getrennt planen']}});
add({profession:'Küche',rank:5,type:'scene',section:'Rechnen',cat:'Kalkulation',title:'Verlust und Ausbeute',prompt:'20 kg Rohgemüse ergeben nach Putzen 15 kg verwendbare Ware. Wie hoch ist der Putzverlust?',scenes:[['25 %','🧮',1],['20 %','🧮',0],['75 %','🧮',0],['33,3 %','🧮',0]],explain:'5 kg Verlust bei 20 kg Rohware entsprechen 5 ÷ 20 × 100 = 25 %.',hint:'Verlustmenge durch Rohmenge mal 100.',math:true});
add({profession:'Bäckerei',rank:4,type:'scene',section:'Rechnen',cat:'Backstuben-Kalkulation',title:'Brötchenteig planen',prompt:'Für 80 Brötchen werden 6,4 kg Teig benötigt. Wie viel Teig brauchst du für 125 Brötchen bei gleichem Stückgewicht?',scenes:[['10,0 kg','🧮',1],['8,0 kg','🧮',0],['9,2 kg','🧮',0],['12,5 kg','🧮',0]],explain:'6,4 kg ÷ 80 = 0,08 kg je Brötchen. 0,08 × 125 = 10,0 kg.',hint:'Stückgewicht zuerst ausrechnen.',math:true});
add({profession:'Bäckerei',rank:5,type:'scene',section:'Rechnen',cat:'Backstuben-Kalkulation',title:'Teigausbeute',prompt:'10 kg Mehl ergeben zusammen mit den übrigen Zutaten 17 kg Teig. Welche Teigausbeute (TA) ergibt sich?',scenes:[['TA 170','🧮',1],['TA 70','🧮',0],['TA 117','🧮',0],['TA 270','🧮',0]],explain:'Teigausbeute = Teigmenge ÷ Mehlmenge × 100. 17 ÷ 10 × 100 = TA 170.',hint:'Teigmenge durch Mehlmenge mal 100.',math:true});
add({profession:'Konditorei',rank:4,type:'scene',section:'Rechnen',cat:'Konditorei-Kalkulation',title:'Dessertmenge hochrechnen',prompt:'Für 24 Dessertgläser brauchst du 1,8 kg Creme. Wie viel Creme brauchst du für 60 Gläser?',scenes:[['4,5 kg','🧮',1],['3,6 kg','🧮',0],['5,0 kg','🧮',0],['6,0 kg','🧮',0]],explain:'1,8 ÷ 24 × 60 = 4,5 kg.',hint:'Menge pro Glas berechnen und auf 60 hochrechnen.',math:true});
add({profession:'Metzgerei',rank:4,type:'scene',section:'Rechnen',cat:'Produktionsrechnung',title:'Brätmenge planen',prompt:'120 Würste sollen je 120 g wiegen. Wie viel Brät wird ohne Produktionsreserve benötigt?',scenes:[['14,4 kg','🧮',1],['12,0 kg','🧮',0],['15,6 kg','🧮',0],['10,0 kg','🧮',0]],explain:'120 × 120 g = 14.400 g = 14,4 kg.',hint:'Stückzahl mal Stückgewicht; anschließend Gramm in Kilogramm umrechnen.',math:true});


