add({rank:0,type:'scene',section:'Materialkunde',cat:'Kochgeschirr',title:'Edelstahl-Kochgeschirr erkennen',photo:'assets/real/cooking_pots.jpg',prompt:'Welche Materialgruppe ist auf dem Bild überwiegend zu sehen?',scenes:[['Edelstahl-Kochgeschirr','',1],['Kunststoff-Geschirr','',0],['Ton-Römertöpfe','',0],['Kupferformen','',0]],explain:'Auf dem Foto ist überwiegend Kochgeschirr aus Edelstahl zu sehen.',hint:'Achte auf die metallisch silberne Oberfläche.',knowledge:{title:'Materialkunde · Edelstahl',text:'Edelstahl ist robust, hygienisch und in professionellen Küchen sehr verbreitet. Bei Mehrschicht- oder Sandwichböden verbessern andere Metalle häufig die Wärmeverteilung.',facts:['robust und korrosionsbeständig','gut zu reinigen','Wärmeverteilung hängt vom Aufbau ab']}});
add({rank:1,type:'scene',section:'Materialkunde',cat:'Pfannen',title:'Unbeschichtete Edelstahlpfanne',photo:'assets/real/frying_pan.jpg',prompt:'Für welche Aufgabe ist diese unbeschichtete Edelstahlpfanne besonders geeignet?',scenes:[['Kräftiges Anbraten und Röstaromen erzeugen','',1],['Eiscreme einfrieren','',0],['Sahne aufschlagen','',0],['Brotteig kneten','',0]],explain:'Eine robuste unbeschichtete Edelstahlpfanne eignet sich gut für hohe Temperaturen und kräftiges Anbraten.',hint:'Denke an hohe Temperatur und Röstaromen.',knowledge:{title:'Materialkunde · Edelstahlpfanne',text:'Unbeschichtete Edelstahlpfannen sind robust und temperaturbeständig. Richtiges Vorheizen, passendes Fett und ein trockener Produktkontakt helfen beim Anbraten.',facts:['hohe Temperatur möglich','Bratensatz für Saucen nutzbar','kein Antihaft-Effekt ohne richtige Technik']}});
add({rank:1,type:'scene',section:'Materialkunde',cat:'Handwerkzeuge',title:'Schneebesen erkennen',photo:'assets/real/whisk.jpg',prompt:'Welche Hauptfunktion hat das sichtbare Werkzeug?',scenes:[['Verrühren, Emulgieren und Luft einarbeiten','',1],['Knochen sägen','',0],['Fleisch plattieren','',0],['Gemüse schälen','',0]],explain:'Der Schneebesen verbindet Flüssigkeiten und kann Luft in Massen einarbeiten.',hint:'Viele dünne Drähte bewegen viel Flüssigkeit und Luft.',knowledge:{title:'Materialkunde · Schneebesen',text:'Je nach Drahtstärke und Form eignen sich Schneebesen für Saucen, Emulsionen, Sahne oder Eiweiß. In beschichteten Gefäßen muss auf materialschonende Werkzeuge geachtet werden.',facts:['Saucen und Emulsionen','Sahne und Eiweiß','Werkzeugmaterial zum Gefäß passend wählen']}});
add({rank:2,type:'scene',section:'Materialkunde',cat:'Messer',title:'Messerfamilie im Bild',photo:'assets/real/kitchen_knives.jpg',prompt:'Welches Merkmal kennzeichnet auf dem Bild das klassische Brotmesser am deutlichsten?',scenes:[['Eine lange Klinge mit Wellenschliff','',1],['Eine kurze flexible Ausbeinklinge','',0],['Ein runder Löffelkopf','',0],['Ein Stahlstab ohne Schneide','',0]],explain:'Das Brotmesser ist vor allem an der langen Klinge mit Wellenschliff erkennbar.',hint:'Suche die gezahnte bzw. gewellte Schneide.',knowledge:{title:'Materialkunde · Messer erkennen',text:'Klingenform und Schneidengeometrie verraten viel über den Einsatzzweck. Wellenschliff greift Krusten, während schmale glatte Klingen präzise Schneid- oder Ausbeinarbeiten ermöglichen.',facts:['Wellenschliff: Brot/Krusten','schmale Klinge: Detail- oder Ausbeinarbeit','Werkzeug nach Aufgabe wählen']}});
add({rank:3,type:'match',section:'Materialkunde',cat:'Kochgeschirr',title:'Kochgeschirr und Bauform',photo:'assets/real/cooking_pots.jpg',prompt:'Ziehe die drei Bauformen direkt auf ihre typische Stärke.',pairs:[['Bratpfanne','große Bratfläche und flacher Rand','🍳'],['Sauteuse','hochgezogener, gerundeter Rand für Saucen und Schwenken','🥘'],['Kochtopf','hoher Rand und Volumen für Flüssigkeiten','🍲']],explain:'Die Bauform des Kochgeschirrs unterstützt die jeweilige Arbeitsweise.',hint:'Flach braten – gerundet schwenken – hoch Flüssigkeit halten.',knowledge:{title:'Materialkunde · Bauformen',text:'Pfanne, Sauteuse und Kochtopf unterscheiden sich nicht nur im Namen. Randform, Bodenfläche und Volumen beeinflussen Verdampfung, Schwenkbarkeit und Temperaturführung.',facts:['Pfanne: Bratfläche','Sauteuse: Saucen/Reduktionen','Topf: Volumen/Flüssigkeit']}});
add({rank:4,type:'match',section:'Materialkunde',cat:'Messer & Pflege',title:'Werkzeug, Klinge und Pflege',prompt:'Ordne die Werkzeuge ihrer fachlichen Hauptaufgabe zu.',pairs:[['Ausbeinmesser','Fleisch dicht an Knochen und Gelenken lösen','🥩'],['Spickmesser','feine Einstiche und präzise kleine Arbeiten','🔪'],['Wetzstahl','Schneidkante geeigneter Messer aufrichten','🗡️'],['Sägemesser','Krusten mit Wellenschliff schneiden','🥖']],explain:'Form, Flexibilität und Schneidengeometrie entscheiden über den sinnvollen Einsatz.',hint:'Knochen – fein/spitz – Pflege – Kruste.',knowledge:{title:'Materialkunde · Profiwerkzeuge',text:'Sichere Messerarbeit beginnt mit dem passenden Werkzeug. Ein scharfes, gepflegtes Messer braucht weniger Kraft und lässt sich kontrollierter führen.',facts:['Ausbeinmesser: schmal','Spickmesser: spitz','Wetzstahl: Pflege','Sägemesser: Wellenschliff']}});
add({rank:5,type:'scene',section:'Materialkunde',cat:'Beschaffung',title:'Kochgeschirr für die Profiküche',prompt:'Welche Entscheidung ist bei der Beschaffung von Kochgeschirr fachlich am sinnvollsten?',scenes:[['Material, Bauform, Herdtechnik, Einsatz, Ergonomie und Reinigbarkeit gemeinsam bewerten','',1],['Nur nach der Farbe entscheiden','',0],['Immer das leichteste Gefäß wählen, unabhängig vom Einsatz','',0],['Beschichtung und Temperaturgrenzen ignorieren','',0]],explain:'Professionelle Beschaffung bewertet den gesamten Einsatzkontext statt nur ein einzelnes Merkmal.',hint:'Eine gute Investition verbindet Technik, Arbeitssicherheit und Prozessnutzen.',knowledge:{title:'Materialkunde · Beschaffung',text:'In der Profiküche zählen neben Anschaffungskosten auch Lebensdauer, Energieübertragung, Ergonomie, Ersatzteil- bzw. Nachbeschaffung und Reinigungsaufwand.',facts:['Lebenszyklus statt nur Kaufpreis','Herdkompatibilität prüfen','Ergonomie und Reinigung mitbewerten']}});


