add({rank:0,type:'scene',section:'Gerätekunde',cat:'Wärmegeräte',title:'Kuchen backen',photo:'assets/real/baking_oven.svg',prompt:'In welchem Gerät lässt sich ein klassischer Kuchen in einer Backform am sinnvollsten backen?',scenes:[['Backofen','♨️',1],['Fritteuse','🍟',0],['Mikrowelle als Standard-Backgerät','📡',0],['Kühlschrank','❄️',0]],explain:'Für klassische Kuchen in Backformen ist der Backofen das passende Standardgerät.',hint:'Gesucht ist trockene, kontrollierbare Backhitze.',knowledge:{title:'Gerätekunde · Backofen',text:'Backöfen übertragen Wärme je nach Bauart über Ober-/Unterhitze, Heißluft oder Umluft. Für Backwaren sind Temperaturstabilität, Vorheizen und eine passende Einschubhöhe wichtig.',facts:['Einsatz: backen · gratinieren · garen','Temperatur vor Arbeitsbeginn prüfen','Tür nicht unnötig häufig öffnen']}});
add({rank:0,type:'scene',section:'Gerätekunde',cat:'Wärmegeräte',title:'Fritteuse',photo:'assets/real/deep_fryer.svg',prompt:'Wofür ist eine Fritteuse in erster Linie vorgesehen?',scenes:[['Lebensmittel in heißem Fett bzw. Öl frittieren','🍟',1],['Suppen kalt halten','❄️',0],['Teig kneten','🥖',0],['Geschirr spülen','🫧',0]],explain:'Eine Fritteuse hält Frittierfett bzw. -öl in einem kontrollierten Temperaturbereich zum Ausbacken von Lebensmitteln.',hint:'Denke an Pommes, Kroketten oder ausgebackene Speisen.',knowledge:{title:'Gerätekunde · Fritteuse',text:'Eine Fritteuse benötigt sauberes, geeignetes Frittiermedium und eine kontrollierte Temperatur. Wasser und nasse Produkte können beim Einsetzen starkes Spritzen verursachen.',facts:['Einsatz: frittieren','Temperatur kontrollieren','Wasser vom heißen Fett fernhalten']}});
add({rank:0,type:'scene',section:'Gerätekunde',cat:'Wärmegeräte',title:'Mikrowelle',photo:'assets/real/open_microwave_oven.svg',prompt:'Wofür ist die Mikrowelle besonders praktisch?',scenes:[['Kleine geeignete Portionen schnell erwärmen oder regenerieren','📡',1],['Knochen zersägen','🪚',0],['Große Kuchen klassisch knusprig ausbacken','🎂',0],['Frittieröl filtern','🍟',0]],explain:'Mikrowellen eignen sich besonders zum schnellen Erwärmen geeigneter Lebensmittel und Portionen.',hint:'Schnelligkeit bei kleinen Mengen ist ihre Stärke.',knowledge:{title:'Gerätekunde · Mikrowelle',text:'Mikrowellen regen polare Moleküle im Lebensmittel an und erwärmen dadurch das Produkt. Bräunung und Krustenbildung sind bei reiner Mikrowellenfunktion begrenzt.',facts:['Schnelles Erwärmen','Geeignetes Geschirr verwenden','Metall nur, wenn das Gerät bzw. Programm es ausdrücklich erlaubt']}});
add({rank:0,type:'scene',section:'Gerätekunde',cat:'Herdarten',title:'Gasherd',photo:'assets/real/gas_stove.svg',prompt:'Woran erkennst du einen klassischen Gasherd?',scenes:[['Die Wärme entsteht durch eine sichtbare Gasflamme am Brenner','🔥',1],['Der Topf wird ausschließlich durch Mikrowellen erwärmt','📡',0],['Es gibt grundsätzlich keine offene Wärmequelle','❄️',0],['Er arbeitet nur mit Holzkohle im Garraum','🪵',0]],explain:'Beim Gasherd erzeugt eine Gasflamme die Wärme direkt unter dem Kochgeschirr.',hint:'Die Flamme ist sichtbar.',knowledge:{title:'Gerätekunde · Gasherd',text:'Gas ermöglicht eine sehr direkte optische und schnelle Leistungsregelung. Gleichzeitig sind Verbrennung, Abwärme und Lüftung sicherheitstechnisch zu berücksichtigen.',facts:['Sichtbare Flamme','Schnelle Leistungsänderung','Lüftung und Gassicherheit beachten']}});
add({rank:1,type:'scene',section:'Gerätekunde',cat:'Herdarten',title:'Induktionsherd',photo:'assets/real/induction_cooktop.svg',prompt:'Welche Voraussetzung muss Kochgeschirr für einen klassischen Induktionsherd grundsätzlich erfüllen?',scenes:[['Der Topfboden muss für Induktion geeignet bzw. magnetisch wirksam sein','🧲',1],['Er muss vollständig aus Holz bestehen','🪵',0],['Er darf keinen Boden besitzen','⭕',0],['Nur Glas funktioniert immer auf jedem Induktionsfeld','🥛',0]],explain:'Induktion benötigt geeignetes Kochgeschirr mit einem ferromagnetisch wirksamen Boden bzw. einer dafür konstruierten Schicht.',hint:'Ein Magnettest am Topfboden ist oft ein praktischer Hinweis.',knowledge:{title:'Gerätekunde · Induktion',text:'Induktion erzeugt Wärme direkt im geeigneten Kochgeschirr. Dadurch reagiert das System schnell und die Kochfläche selbst wird vor allem durch den heißen Topf erwärmt.',facts:['Geeignetes Kochgeschirr erforderlich','Schnelle Regelung','Geringere direkte Abwärme als viele konventionelle Systeme']}});
add({rank:1,type:'scene',section:'Gerätekunde',cat:'Herdarten',title:'Elektroherd',prompt:'Was ist bei einer klassischen elektrischen Kochplatte oder Glaskeramikzone nach dem Ausschalten besonders zu beachten?',scenes:[['Es kann deutliche Restwärme vorhanden sein','♨️',1],['Die Fläche ist immer sofort eiskalt','❄️',0],['Der Topf wird danach magnetisch','🧲',0],['Die Kochzone füllt sich mit Wasser','💧',0]],explain:'Elektrische Kochzonen können nach dem Ausschalten noch längere Zeit Restwärme abgeben.',hint:'Ausschalten bedeutet nicht automatisch kalt.',knowledge:{title:'Gerätekunde · Elektrokochfeld',text:'Elektrische Widerstandsheizungen erwärmen Kochplatte oder Glaskeramik, die Wärme anschließend an das Kochgeschirr weitergeben. Restwärme kann bewusst genutzt werden, ist aber auch ein Verbrennungsrisiko.',facts:['Restwärme beachten','Träger reagiert träger als Induktion','Kochzone passend zum Topfdurchmesser wählen']}});
add({rank:1,type:'match',section:'Gerätekunde',cat:'Herdarten',title:'Herdarten zuordnen',prompt:'Ziehe jede Herdart auf ihr typisches Merkmal.',pairs:[['Gasherd','sichtbare Flamme und direkte Leistungsänderung','🔥'],['Induktion','Wärmeerzeugung im geeigneten Kochgeschirr','🧲'],['Elektro/Glaskeramik','Heizelement erwärmt zunächst die Kochzone','♨️']],explain:'Gas arbeitet mit Flamme, Induktion erzeugt Wärme im geeigneten Topf und Elektrokochfelder erwärmen die Kochzone über Heizelemente.',hint:'Flamme – Magnetfeld – Heizelement.'});
add({rank:1,type:'scene',section:'Gerätekunde',cat:'Backofen',title:'Umluft / Heißluft',prompt:'Welches Merkmal ist für Umluft- bzw. Heißluftbetrieb typisch?',scenes:[['Ein Ventilator bewegt die heiße Luft im Garraum','💨',1],['Das Gerät kühlt Lebensmittel ausschließlich herunter','❄️',0],['Nur eine offene Gasflamme berührt den Kuchen','🔥',0],['Das Gargut liegt im Frittieröl','🍟',0]],explain:'Bei Umluft oder Heißluft sorgt ein Gebläse für Luftbewegung und damit eine gleichmäßigere Wärmeverteilung.',hint:'Denke an Luftbewegung im Garraum.',knowledge:{title:'Gerätekunde · Umluft und Heißluft',text:'Ein Gebläse verteilt heiße Luft im Garraum. Je nach Gerät und Produkt können mehrere Ebenen genutzt werden; Temperatur und Luftgeschwindigkeit müssen zum Produkt passen.',facts:['Gebläse verteilt Wärme','Mehrere Ebenen möglich','Empfindliche Backwaren reagieren auf zu starke Luftbewegung']}});
add({rank:2,type:'scene',section:'Gerätekunde',cat:'Mikrowelle',title:'Geeignetes Geschirr',prompt:'Welche Grundregel ist bei einer normalen Mikrowellenfunktion am sichersten?',scenes:[['Nur mikrowellengeeignetes Geschirr verwenden und Herstellerangaben beachten','✅',1],['Jede beliebige Metallschüssel ist grundsätzlich unproblematisch','⚠️',0],['Geschlossene Konservendosen direkt erhitzen','🥫',0],['Nie auf die Gerätehinweise achten','🙈',0]],explain:'Bei Mikrowellenbetrieb sind geeignetes Geschirr und die Vorgaben des Geräteherstellers entscheidend.',hint:'Das Gerät gibt vor, welche Materialien zulässig sind.',knowledge:{title:'Gerätekunde · Mikrowellensicherheit',text:'Nicht jedes Material ist für Mikrowellen geeignet. Besonders Metallteile, geschlossene Behälter und ungeeignete Kunststoffe können problematisch sein.',facts:['Herstellerangaben beachten','Behälter nicht druckdicht verschließen','Geeignetes Geschirr einsetzen']}});
add({rank:2,type:'scene',section:'Gerätekunde',cat:'Fritteuse',title:'Frittierkorb richtig beladen',prompt:'Was passiert typischerweise, wenn du zu viel kaltes oder sehr feuchtes Gargut auf einmal in die Fritteuse gibst?',scenes:[['Die Fetttemperatur fällt stark ab und das Ergebnis kann fettiger bzw. ungleichmäßig werden','🌡️',1],['Das Fett wird automatisch kälteresistent','🧊',0],['Das Gargut wird grundsätzlich sofort trocken','✨',0],['Die Fritteuse verwandelt sich in einen Backofen','♨️',0]],explain:'Zu große oder sehr kalte Chargen senken die Fetttemperatur. Feuchtigkeit fördert außerdem Spritzen und Schaumbildung.',hint:'Eine Fritteuse hat nur begrenzte Heizleistung.',knowledge:{title:'Gerätekunde · Frittierleistung',text:'Beladungsmenge, Produkttemperatur und Feuchtigkeit beeinflussen die Temperaturstabilität und Produktqualität stark.',facts:['Nicht überladen','Oberflächenwasser vermeiden','Fetttemperatur kontrollieren']}});
add({rank:2,type:'scene',section:'Gerätekunde',cat:'Herdarten',title:'Kohle- und Festbrennstoffherd',prompt:'Welche Aussage trifft auf historische bzw. traditionelle Kohle- oder Festbrennstoffherde am ehesten zu?',scenes:[['Sie reagieren langsamer auf Leistungsänderungen und erfordern Brennstoff-, Asche- und Abgasmanagement','🪵',1],['Sie schalten ihre Wärme in Millisekunden elektronisch ab','⚡',0],['Sie benötigen grundsätzlich kein Abgassystem','🚫',0],['Sie arbeiten ausschließlich mit Induktionsspulen','🧲',0]],explain:'Festbrennstoffherde sind vergleichsweise träge und verlangen Brennstoffführung, Ascheentsorgung und sichere Abgasführung.',hint:'Feuer und Brennstoff lassen sich nicht wie Elektronik regeln.',knowledge:{title:'Gerätekunde · Festbrennstoffherd',text:'Kohle- und Holzherde prägten historische Küchen. Sie speichern viel Wärme, sind aber in der Regel träger zu regeln und verlangen eine sichere Abgasführung.',facts:['Hohe Wärmespeicherung','Trägere Regelung','Abgas und Asche beachten']}});
add({rank:2,type:'match',section:'Gerätekunde',cat:'Wärmegeräte',title:'Gerät und Verwendung',prompt:'Ordne jedes Gerät seiner typischen Hauptanwendung zu.',pairs:[['Backofen','backen und garen mit trockener bzw. zirkulierender Hitze','♨️'],['Fritteuse','Garen in heißem Fett oder Öl','🍟'],['Mikrowelle','schnelles Erwärmen geeigneter Lebensmittel','📡']],explain:'Backofen, Fritteuse und Mikrowelle übertragen Energie auf sehr unterschiedliche Weise und eignen sich deshalb für unterschiedliche Aufgaben.',hint:'Backen – Fett – schnelles Erwärmen.'});
add({rank:3,type:'scene',section:'Gerätekunde',cat:'Herdarten',title:'Schnell regelbare Kochstelle',prompt:'Du musst eine empfindliche Sauce sehr schnell von hoher auf geringe Heizleistung umstellen. Welches System reagiert bei geeignetem Kochgeschirr besonders direkt?',scenes:[['Induktion','🧲',1],['Ein träger Kohleherd mit großer Glutmasse','🪵',0],['Glaskeramik mit hoher Restwärme und träger Nachregelung','♨️',0],['Ein schwerer Gussplattenherd mit großer Wärmespeicherung','🔥',0]],explain:'Induktion kann die eingebrachte Leistung sehr schnell verändern und eignet sich deshalb gut für fein regelbare Kochprozesse.',hint:'Gesucht ist die elektrisch besonders reaktionsschnelle Herdart.',knowledge:{title:'Gerätekunde · Regelverhalten',text:'Für empfindliche Kochprozesse sind schnelle Leistungsänderung und reproduzierbare Stufen hilfreich. Gas und Induktion reagieren deutlich direkter als viele träge Wärmespeicher.',facts:['Induktion: sehr schnell regelbar','Gas: ebenfalls direkte Regelung','Festbrennstoff: deutlich träger']}});
add({rank:3,type:'scene',section:'Gerätekunde',cat:'Backofen',title:'Backofentür und Kuchen',prompt:'Warum sollte die Backofentür bei empfindlichen Kuchen nicht unnötig oft geöffnet werden?',scenes:[['Temperatur und Garraumatmosphäre können stark einbrechen und das Backergebnis beeinträchtigen','🎂',1],['Die Oberfläche bräunt grundsätzlich stärker, während der Kern unverändert bleibt','🎂',0],['Nur die Luftfeuchte steigt, die Temperatur bleibt vollständig konstant','💨',0],['Die Backzeit verkürzt sich dadurch immer zuverlässig','⏱️',0]],explain:'Häufiges Öffnen lässt Wärme entweichen und kann bei empfindlichen Massen Volumen und Struktur beeinträchtigen.',hint:'Stabilität braucht eine möglichst konstante Backumgebung.',knowledge:{title:'Gerätekunde · Backstabilität',text:'Temperatur, Luftbewegung, Feuchte und Zeit beeinflussen das Backergebnis. Empfindliche Massen reagieren besonders auf starke Temperaturschwankungen.',facts:['Tür nur bei Bedarf öffnen','Temperaturstabilität erhalten','Produkt und Rezeptur bestimmen das Backprogramm']}});
add({rank:3,type:'scene',section:'Gerätekunde',cat:'Fritteuse',title:'Frittierfett beurteilen',prompt:'Welche Vorgehensweise ist professionell?',scenes:[['Frittiermedium regelmäßig prüfen, filtern bzw. wechseln und Temperatur sowie Hersteller-/Betriebsvorgaben einhalten','✅',1],['Frittiermedium nur nach Betriebsstunden wechseln, unabhängig von Messwerten und Sensorik','⏱️',0],['Altes Medium ausschließlich durch Zugabe von frischem Öl regenerieren','🫗',0],['Temperaturkontrolle genügt; Filtration und Produktreste spielen keine Rolle','🌡️',0]],explain:'Frittiermedium altert durch Hitze, Sauerstoff, Wasser und Produktreste. Kontrolle und Pflege sind Qualitäts- und Sicherheitsaufgaben.',hint:'Qualität muss überwacht werden.',knowledge:{title:'Gerätekunde · Frittiermedium',text:'Frittierfett bzw. -öl verändert sich während der Nutzung. Betrieblich sind sensorische Prüfung, Filtration, Temperaturkontrolle und definierte Wechselkriterien wichtig.',facts:['Produktreste entfernen','Überhitzung vermeiden','Wechselkriterien dokumentieren']}});
add({rank:4,type:'scene',section:'Gerätekunde',cat:'Produktionsgeräte',title:'Kombidämpfer',prompt:'Was ist die besondere Stärke eines Kombidämpfers?',scenes:[['Er kombiniert Heißluft und Dampf in steuerbaren Betriebsarten','💨',1],['Er arbeitet ausschließlich mit trockener Heißluft ohne Feuchtesteuerung','♨️',0],['Er erzeugt Dampf nur passiv aus dem Gargut und kann ihn nicht steuern','💧',0],['Er ist primär ein Warmhaltegerät ohne Garprogramme','🌡️',0]],explain:'Kombidämpfer können trockene Heißluft, Dampf und kombinierte Feuchte-/Hitzeprogramme nutzen.',hint:'Der Name verrät: zwei Wärme-/Feuchteprinzipien werden kombiniert.',knowledge:{title:'Gerätekunde · Kombidämpfer',text:'Kombidämpfer verbinden Heißluft und Dampf. Dadurch lassen sich viele Garprozesse reproduzierbar steuern; Beladung, Kerntemperatur, Feuchte und Programmwahl bleiben entscheidend.',facts:['Heißluft + Dampf','Reproduzierbare Programme','Beladung und Luftführung beachten']}});
add({rank:4,type:'scene',section:'Gerätekunde',cat:'Produktionsgeräte',title:'Salamander',prompt:'Wofür wird ein Salamander in der professionellen Küche typischerweise eingesetzt?',scenes:[['Zum schnellen Überbacken, Gratinieren und Bräunen von oben','🔥',1],['Zum langsamen Schmoren großer Fleischstücke in feuchter Hitze','🥘',0],['Zum kontrollierten Niedertemperaturgaren im Wasserbad','🌡️',0],['Zum Regenerieren mit gesättigtem Dampf','💨',0]],explain:'Ein Salamander liefert intensive Oberhitze und eignet sich besonders zum schnellen Gratinieren und Nachbräunen.',hint:'Starke Hitze von oben.',knowledge:{title:'Gerätekunde · Salamander',text:'Der Salamander ist ein Oberhitzegerät. Er wird für Gratins, Überbacken, Nachbräunen und teilweise Warmhalten eingesetzt.',facts:['Starke Oberhitze','Kurze Einsatzzeiten','Produkt genau beobachten']}});
