add({rank:2,profession:'Küche',type:'match',cat:'Warenkunde',section:'Fischkunde',title:'Fischart und Garverfahren',prompt:'Ordne eine fachlich sinnvolle Zubereitung zu.',pairs:[['Kabeljaufilet','pochieren, dämpfen oder schonend braten','🐟'],['Lachsfilet','braten, grillen oder schonend im Ofen garen','🐟'],['Seezungenfilet','kurz sautieren oder pochieren','🐟'],['Fischkarkasse','Fischfond ansetzen','🦴']],explain:'Fischart, Fettgehalt und Filetdicke bestimmen die geeignete Gartechnik. Karkassen werden dagegen als Aromageber für Fond verwendet.',hint:'Karkasse gehört in den Fond, zarte Filets brauchen kurze Garzeiten.'});
add({rank:2,profession:'Küche',type:'sequence',cat:'Warenkunde',section:'Fischkunde',title:'Rundfisch filetieren · Grundfolge',photo:'assets/real/fish_filleting.svg',prompt:'Bringe die vereinfachte Arbeitsfolge in eine sinnvolle Reihenfolge.',items:['Filet von den Gräten lösen','Fisch vorbereiten und Flossen kontrollieren','Schnitt hinter dem Kopf setzen','Entlang der Mittelgräte arbeiten','Filet parieren und Gräten prüfen'],answer:['Fisch vorbereiten und Flossen kontrollieren','Schnitt hinter dem Kopf setzen','Entlang der Mittelgräte arbeiten','Filet von den Gräten lösen','Filet parieren und Gräten prüfen'],explain:'Beim Filetieren wird kontrolliert entlang des Skeletts gearbeitet, damit möglichst wenig Fleisch an der Karkasse verbleibt.',hint:'Vorbereiten, Kopfbereich öffnen, Mittelgräte führen, lösen, parieren.'});
add({rank:3,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',title:'Fischfrische beurteilen',prompt:'Welche Kombination spricht bei einem ganzen Frischfisch am ehesten für gute Frische?',scenes:[['Klare gewölbte Augen, rote bis rosige Kiemen, frischer Geruch und elastisches Fleisch','🐟',1],['Trübe eingesunkene Augen, graue Kiemen und stechender Geruch','🐟',0],['Weiche Druckstellen und stark ammoniakalischer Geruch','🐟',0],['Trockene Haut und braune Kiemen als eindeutiges Frischezeichen','🐟',0]],explain:'Frische wird aus mehreren sensorischen Merkmalen gemeinsam beurteilt – nicht aus nur einem einzelnen Zeichen.',hint:'Augen, Kiemen, Geruch und Elastizität zusammen bewerten.',knowledge:{title:'Fischkunde · Frische',text:'Bei ganzem Fisch werden Augen, Kiemen, Haut, Geruch und Fleischfestigkeit gemeinsam beurteilt. Ein frischer, unaufdringlicher Geruch ist wichtig.',facts:['klare Augen','frische Kiemenfarbe','elastisches Fleisch','neutral-frischer Geruch']}});
add({rank:3,profession:'Küche',type:'multi',cat:'Warenkunde',section:'Fischkunde',title:'Fischfond – geeigneter Ansatz',prompt:'Welche 4 Bestandteile passen fachlich zu einem klassischen hellen Fischfond?',dish:'🐟',caption:'Fischfond',inside:['heller Ansatz'],choices:[c('Fischkarkassen und Abschnitte geeigneter Magerfische','🦴',1),c('Mirepoix/helle Aromaten','🥕',1),c('Weißwein je nach Rezeptur','🍷',1),c('Wasser','💧',1),c('kräftig geröstete Fischkarkassen','🐟',0),c('dunkle Kalbsjus','🥘',0),c('Sahne als Grundflüssigkeit','🥛',0)],need:4,answer:['Fischkarkassen und Abschnitte geeigneter Magerfische','Mirepoix/helle Aromaten','Weißwein je nach Rezeptur','Wasser'],explain:'Ein klassischer Fischfond wird hell und relativ kurz geführt. Stark geröstete Fleischknochen oder dunkle Saucengrundlagen passen nicht dazu.',hint:'Hell, frisch und fischtypisch – nicht dunkel und fleischlastig.'});
add({rank:4,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',title:'Plattfisch filetieren',prompt:'Wie viele Filets erhält man bei der klassischen Filetierung eines Plattfisches typischerweise?',scenes:[['Vier Filets – zwei von jeder Körperseite','🐟',1],['Zwei Filets – grundsätzlich nur eines je Körperseite','🐟',0],['Sechs Filets – immer drei je Seite','🐟',0],['Nur ein Filet – der Rest ist Karkasse','🐟',0]],explain:'Plattfische besitzen eine andere Körperform als Rundfische. Klassisch werden vier Filets ausgelöst.',hint:'Ein Plattfisch wird anders zerlegt als ein Rundfisch.',knowledge:{title:'Fischkunde · Filetierung',text:'Bei Rundfischen werden typischerweise zwei Hauptfilets ausgelöst, bei Plattfischen vier. Das ist ein zentraler Unterschied in der praktischen Fischkunde.',facts:['Rundfisch: zwei Hauptfilets','Plattfisch: vier Filets','Karkasse für geeigneten Fischfond nutzbar']}});
add({rank:4,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',title:'Fettfisch im Menü',prompt:'Welcher Punkt sollte bei einem fettreichen Fisch wie Lachs im Menü besonders bedacht werden?',scenes:[['Fettgehalt, Portionsgröße und Begleitung so abstimmen, dass das Gericht nicht zu schwer wirkt','🐟',1],['Zusätzlich möglichst viel schwere Butter- und Sahnesauce einplanen, unabhängig vom restlichen Menü','🥛',0],['Fettgehalt spielt für Menüdramaturgie grundsätzlich keine Rolle','🍽️',0],['Lachs darf nur kalt serviert werden','❄️',0]],explain:'Fettreiche Fische bringen bereits viel Saftigkeit und Eigengeschmack mit. Säure, Gemüse und leichtere Saucen können das Gericht ausbalancieren.',hint:'Menüplanung heißt nicht nur Garen, sondern auch Balance.'});
add({rank:5,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',title:'Fisch am Pass übergart',prompt:'Mehrere Fischportionen kommen trocken am Pass an. Welche Analyse ist fachlich zuerst sinnvoll?',scenes:[['Kerntemperatur/Gargrad, Portionsstärke, Garzeit, Nachgarung und Warmhaltezeit gemeinsam prüfen','🐟',1],['Nur mehr Sauce darübergeben und den Garprozess unverändert lassen','🥣',0],['Fisch grundsätzlich dicker panieren','🌾',0],['Garzeiten künftig ohne Bezug zur Portionsgröße verlängern','⏱️',0]],explain:'Fisch übergart schnell. Professionelle Fehleranalyse betrachtet Produktdicke, Garverfahren, Nachgarung und Wartezeit zusammen.',hint:'Suche die Prozessursache statt sie mit Sauce zu verdecken.'});
add({rank:6,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',title:'Fischsortiment planen',prompt:'Welche Entscheidung ist für eine professionelle Fischkarte am belastbarsten?',scenes:[['Saison, Verfügbarkeit, Qualität, Herkunft, Kühlkette, Ausbeute, Garverfahren und Menübalance gemeinsam bewerten','📋',1],['Nur den niedrigsten Einkaufspreis betrachten','💶',0],['Jeden Fisch unabhängig von Saison und Lieferqualität fest einplanen','📅',0],['Ausbeute und Kühlkette nicht berücksichtigen','🙈',0]],explain:'Auf Leitungsebene gehören Qualität, Wirtschaftlichkeit, Verfügbarkeit und sichere Prozessführung zusammen.',hint:'Nicht ein einzelner Faktor entscheidet über eine professionelle Karte.'});

