add({rank:4,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',difficulty:5,title:'Ribeye / Entrecôte',prompt:'Welche Aussage ist fachlich am treffendsten?',scenes:[['Ribeye bzw. Entrecôte stammt aus dem vorderen Rücken/Hochrippenbereich des Rindes und eignet sich sehr gut zum Kurzbraten als Steak','🥩',1],['Ribeye ist die klassische Bezeichnung für die Rinderwade und wird vor allem geschmort','🍲',0],['Ribeye bezeichnet beim Schwein ausschließlich den Bauch','🐖',0],['Ribeye ist ein Oberbegriff für jede Art von Hackfleisch','🔪',0]],explain:'Ribeye bzw. Entrecôte ist ein stark aromatischer Rücken-Zuschnitt des Rindes. Die intramuskuläre Fettmarmorierung macht ihn besonders saftig und steakgeeignet.',hint:'Denke an Hochrippe, Marmorierung und Kurzbraten.',knowledge:{title:'Rind · Ribeye / Entrecôte',text:'Ribeye oder Entrecôte stammt aus dem vorderen Rückenbereich des Rindes. Es ist kräftig aromatisch, gut marmoriert und klassisch für Steaks, Kurzbraten und rosa Garung geeignet.',facts:['Bereich: vorderer Rücken/Hochrippe','gut marmoriert','Verwendung: Steak · Kurzbraten · rosa garen']}});
add({rank:4,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',difficulty:5,title:'Roastbeef oder Filet?',prompt:'Welches Teilstück liefert klassisch Rumpsteaks und kann im Ganzen als Roastbeef rosa gebraten werden?',scenes:[['Roastbeef / Rücken','🍖',1],['Filetspitze','🥩',0],['Brust / Querrippe','🍲',0],['Wade','🥘',0]],explain:'Rumpsteaks stammen klassisch aus dem Roastbeef bzw. Rücken. Dieses Stück kann im Ganzen rosa gebraten und tranchiert werden.',hint:'Gesucht ist nicht das Filet, sondern der kräftige Rückenstrang.',knowledge:{title:'Rind · Roastbeef',text:'Das Roastbeef liegt im Rücken des Rindes. Daraus entstehen unter anderem Rumpsteaks; im Ganzen ist es als Roastbeef ein klassischer Bratenzuschnitt.',facts:['Teil des Rückens','liefert Rumpsteaks','im Ganzen rosa braten möglich']}});
add({rank:5,profession:'Küche',type:'multi',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',difficulty:6,title:'Rinderfilet – klassische Zuschnitte',prompt:'Welche 4 Bezeichnungen stehen in klassischer Küchenfachsprache für typische Filetzuschnitte oder Filetverwendungen?',dish:'🥩',caption:'Edelstück',inside:['Rinderfilet'],choices:[c('Mignon','🥩',1),c('Tournedos','🍖',1),c('Chateaubriand','🥩',1),c('Filetmedaillon','🥩',1),c('Beinscheibe','🍲',0),c('Roulade','🥘',0),c('Siedfleisch','🍲',0)],need:4,answer:['Mignon','Tournedos','Chateaubriand','Filetmedaillon'],explain:'Zum Rinderfilet gehören klassische Zuschnitte wie Mignon, Tournedos, Filetmedaillon und das größere Chateaubriand aus dem Mittelstück.',hint:'Suche die edlen Kurzbrat- oder Bratenzuschnitte des Filets.',knowledge:{title:'Rind · Filetzuschnitte',text:'Das Rinderfilet liefert mehrere klassische Zuschnitte. Mignon und Medaillon sind kleinere Stücke, Tournedos kräftigere Medaillons und Chateaubriand stammt traditionell aus dem Mittelstück.',facts:['Mignon: kleiner Filetzuschnitt','Tournedos/Medaillon: klassische Kurzbratstücke','Chateaubriand: Mittelstück des Filets']}});
add({rank:5,profession:'Metzgerei',type:'scene',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',title:'Schinken fachlich untergliedern',prompt:'Aus welchem Hauptteilstück stammen Oberschale, Unterschale, Nuss und Hüfte?',scenes:[['Aus dem Schinken bzw. der Keule','🍖',1],['Aus dem Schweinebauch','🥓',0],['Aus der Vorderhaxe','🍲',0],['Aus dem Kopf/der Backe','🥩',0]],explain:'Oberschale, Unterschale, Nuss und Hüfte sind klassische Unterteilungen des Schinkens bzw. der Keule. Sie liefern hochwertige Zuschnitte für Schnitzel, Braten oder Schinkenprodukte.',hint:'Gesucht ist die große Hinterpartie des Schweins.',knowledge:{title:'Schwein · Schinken',text:'Der Schinken bildet das große Hinterviertel des Schweins. Fachlich werden dort unter anderem Oberschale, Unterschale, Nuss und Hüfte unterschieden.',facts:['Hinterviertel / Keule','Unterteilungen: Oberschale · Unterschale · Nuss · Hüfte','Verwendung: Schnitzel · Braten · Schinken']}});
add({rank:4,profession:'Metzgerei',type:'match',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',title:'Schwein – Teilstück und Fachverwendung',prompt:'Ordne die Teilstücke der fachlich typischen Hauptverwendung zu.',pairs:[['Nacken','saftige Steaks, Braten, Pulled Pork','🥩'],['Filet','Medaillons, Mignon, zarte Kurzbratgerichte','🍖'],['Bauch','Speck, Rollbraten, kräftige Schmorgerichte','🥓'],['Schinken','Schnitzel, Braten, Koch- und Rohschinken','🍖']],explain:'Nicht nur die Lage am Tier, sondern auch Fettanteil, Bindegewebe und Muskelfaser entscheiden über die typische Verwendung eines Teilstücks.',hint:'Marmoriert = saftig, zart = kurzbraten, fettreich = Speck oder Rollbraten, mager = Schnitzel/Schinken.',knowledge:{title:'Schwein · Verwendung',text:'Die typische Verwendung eines Teilstücks hängt von Zartheit, Marmorierung und Bindegewebe ab. Genau daraus ergeben sich Zuschnitte wie Steaks, Schnitzel, Braten oder Schmorstücke.',facts:['Nacken: marmoriert und saftig','Filet: sehr zart','Bauch: fettreich','Schinken: mageres Hinterteil']}});
add({rank:6,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Teilstücke & Fleischkunde',difficulty:7,title:'Steakplanung für das Menü',prompt:'Ein Menü verlangt ein saftiges, gut marmoriertes Rindersteak mit kräftigem Eigengeschmack. Welche Wahl ist fachlich am schlüssigsten?',scenes:[['Ribeye / Entrecôte','🥩',1],['Rinderwade','🍲',0],['Rinderbrust','🍲',0],['Suppenknochen','🦴',0]],explain:'Für ein saftiges, aromatisches Steak mit deutlicher Marmorierung ist Ribeye/Entrecôte eine sehr schlüssige Wahl. Wade und Brust sind dagegen eher Langgarstücke.',hint:'Gesucht ist das steaktypische, gut marmorierte Rückenstück.',knowledge:{title:'Menüplanung · Steak',text:'Bei der Steakwahl zählen Aroma, Marmorierung, Zartheit und Garziel. Ribeye/Entrecôte ist für saftige, aromatische Steaks besonders beliebt.',facts:['gut marmoriert','kräftiger Eigengeschmack','klassisches Steakstück']}});


add({rank:1,difficulty:3,type:'multi',cat:'Gerichte & Zutaten',section:'Gerichte & Zutaten',title:'Hühnerfrikassee – typische Einlagen',prompt:'Welche 2 Einlagen gelten in vielen klassischen deutschen Lehrrezepturen als besonders typisch?',dish:'🍲',caption:'ähnliche Gemüsealternativen',inside:['Huhn','helle Sauce'],choices:[c('Champignons','🍄',1),c('Spargel','🌱',1),c('Kohlrabi','🥬',0),c('Zuckerschoten','🫛',0),c('Blumenkohlröschen','🥦',0),c('Lauch','🌿',0)],need:2,answer:['Champignons','Spargel'],explain:'Champignons und Spargel sind klassische, häufig gelehrte Einlagen. Die anderen Gemüse wären kulinarisch durchaus möglich, gehören aber nicht zur typischen Grundvariante.',hint:'Alle Antworten wären essbar – gesucht ist die klassische Lehrbuchkombination.'});
add({rank:2,difficulty:4,type:'multi',cat:'Saucenkunde',section:'Saucenkunde',title:'Hollandaise – was gehört wirklich zur Basis?',prompt:'Welche 3 Komponenten bilden das klassische Grundprinzip der Sauce Hollandaise?',dish:'🥣',caption:'enge Fachalternativen',inside:['warme Emulsion'],choices:[c('Eigelb','🥚',1),c('geklärte/warme Butter','🧈',1),c('Säure bzw. Reduktion','🍋',1),c('Sahne','🥛',0),c('helle Mehlschwitze','🌾',0),c('heller Geflügelfond','🥣',0)],need:3,answer:['Eigelb','geklärte/warme Butter','Säure bzw. Reduktion'],explain:'Hollandaise ist eine warme Emulsion aus Eigelb und Butter mit einer säuerlichen Komponente. Sahne, Roux oder Fond können in anderen Saucen sinnvoll sein, sind aber nicht die klassische Basis.',hint:'Unterscheide Emulsionssauce von gebundener Grundsauce oder Rahmsauce.'});
add({rank:3,difficulty:5,type:'scene',cat:'Fleischkunde',section:'Teilstücke & Fleischkunde',title:'Rückenstück richtig wählen',prompt:'Du brauchst ein gut marmoriertes Rindersteak mit kräftigem Eigengeschmack. Welche Wahl ist fachlich am passendsten?',scenes:[['Entrecôte / Ribeye aus der Hochrippe','🥩',1],['Rumpsteak aus dem Roastbeef','🍖',0],['Filetsteak aus dem Filetmittelstück','🥩',0],['Hüftsteak aus der Hüfte','🍖',0]],explain:'Alle vier Zuschnitte können als Steak eingesetzt werden. Für ausdrücklich starke Marmorierung und kräftigen Eigengeschmack ist Entrecôte/Ribeye typischerweise die passendste Wahl.',hint:'Hier ist nicht gefragt, welches Stück überhaupt ein Steak ergibt, sondern welches die genannten Eigenschaften am besten erfüllt.'});
add({rank:4,difficulty:6,type:'scene',cat:'Fleischkunde',section:'Teilstücke & Fleischkunde',title:'Filet oder Roastbeef im Ganzen?',prompt:'Welcher Zuschnitt passt am besten, wenn ein kräftiger Rinderrücken im Ganzen rosa gebraten und anschließend in Scheiben tranchiert werden soll?',scenes:[['Roastbeef','🍖',1],['Chateaubriand','🥩',0],['Filet Mignon','🥩',0],['Tournedos','🥩',0]],explain:'Roastbeef ist ein Rückenstück und eignet sich sehr gut zum Braten im Ganzen. Chateaubriand, Mignon und Tournedos sind Filetzuschnitte mit anderer Portionierungslogik.',hint:'Achte auf „Rücken“, „im Ganzen“ und späteres Tranchieren.'});
add({rank:4,difficulty:6,type:'multi',cat:'Klassische Küche',section:'Gerichte & Zutaten',title:'Béarnaise – aromatische Signatur',prompt:'Welche 3 Komponenten kennzeichnen die klassische Aromatik einer Béarnaise besonders?',dish:'🥣',caption:'Ableitung der Hollandaise',inside:['warme Buttersauce'],choices:[c('Estragon','🌿',1),c('Schalotten-Essig-Reduktion','🧅',1),c('Kerbel','🌿',1),c('Schnittlauch','🌿',0),c('Petersilie','🌿',0),c('Dijon-Senf','🟡',0)],need:3,answer:['Estragon','Schalotten-Essig-Reduktion','Kerbel'],explain:'Estragon, Kerbel und eine aromatische Schalotten-Essig-Reduktion prägen die klassische Béarnaise. Die falschen Kräuter sind bewusst ähnlich gewählt.',hint:'Mehrere Kräuter wirken plausibel – gesucht sind die klassischen Béarnaise-Aromaten.'});

