add({rank:0,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Salbei erkennen',photo:'assets/real/sage_bundle.svg',prompt:'Für welches klassische Gericht ist Salbei besonders typisch?',scenes:[['Saltimbocca alla Romana','🌿',1],['Vanillepudding','🍮',0],['Apfelpfannkuchen','🍎',0],['Hefezopf','🥖',0]],explain:'Salbei ist klassisch mit Saltimbocca verbunden. Er harmoniert außerdem mit Kalb, Geflügel und brauner Butter.',hint:'Denke an Kalb, Schinken und ein darübergelegtes Blatt.',knowledge:{title:'Kräuterkunde · Salbei',text:'Salbei besitzt ein würzig-harziges, leicht kampferartiges Aroma. Klassisch passt er zu Kalb, Geflügel, brauner Butter, Gnocchi und Saltimbocca alla Romana.',facts:['Aroma: würzig-harzig','klassisch: Saltimbocca','passt zu Kalb, Butter, Gnocchi']}});
add({rank:0,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Basilikum erkennen',photo:'assets/real/basil_bundle.svg',prompt:'Wofür wird Basilikum klassisch besonders gern verwendet?',scenes:[['Pesto alla Genovese und Tomatengerichte','🌿',1],['Sauerbraten und Rotkohl','🥘',0],['Milchreis und Grießpudding','🍚',0],['Panierte Schnitzel ausschließlich','🍖',0]],explain:'Basilikum ist typisch für Pesto, Tomatensaucen und Caprese. Das Kraut mag eher kurze Wärmeeinwirkung.',hint:'Denk an Italien, Tomate und Olivenöl.',knowledge:{title:'Kräuterkunde · Basilikum',text:'Basilikum ist ein klassisches Mittelmeerkraut. Besonders gut passt es zu Tomate, Mozzarella, Pasta, Pesto und leichten Sommersalaten.',facts:['klassisch: Pesto · Caprese','zu viel Hitze mindert das Aroma','gut mit Tomate und Mozzarella']}});
add({rank:1,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Dill erkennen',photo:'assets/real/dill_bundle.svg',prompt:'Zu welchen Speisen passt Dill besonders gut?',scenes:[['Fisch, Gurkensalat und feine Senfsaucen','🌿',1],['Schokoladenmousse und Brownies','🍫',0],['Gulasch ungarischer Art ausschließlich','🥘',0],['Rinderrouladen mit Rotkohl','🍖',0]],explain:'Dill passt klassisch zu Fisch, Gurke, Kartoffeln und hellen Senf- oder Rahmsaucen.',hint:'Das Kraut ist sehr beliebt zu Gurke und Fisch.',knowledge:{title:'Kräuterkunde · Dill',text:'Dill besitzt ein frisches, leicht anisartiges Aroma. Es passt besonders zu Fischgerichten, Gurkensalat, Kartoffeln und hellen Senf- oder Rahmsaucen.',facts:['passt zu Fisch','klassisch zu Gurke','nicht zu lange stark erhitzen']}});
add({rank:1,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Rosmarin erkennen',photo:'assets/real/rosemary_bundle.svg',prompt:'Welche Verwendung ist für Rosmarin am typischsten?',scenes:[['Lamm, Ofenkartoffeln und mediterrane Braten','🌿',1],['Vanillesauce und Kirschkompott','🍒',0],['Fischsülze mit Gurke','🐟',0],['Milchsuppe','🥛',0]],explain:'Rosmarin ist kräftig, harzig und hitzestabil. Typisch sind Lamm, Kartoffeln und mediterrane Braten.',hint:'Denke an Mittelmeeraroma und Bratkartoffeln aus dem Ofen.',knowledge:{title:'Kräuterkunde · Rosmarin',text:'Rosmarin verträgt Hitze gut und wird gern zum Braten und Schmoren mitgegart. Das intensive, harzige Aroma passt zu Lamm, Kartoffeln, Geflügel und mediterranen Schmorgerichten.',facts:['hitzestabil','typisch zu Lamm','sparsam dosieren']}});
add({rank:2,profession:'Küche',type:'match',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Kräuter und typische Verwendung',prompt:'Ordne die Kräuter den fachlich typischen Anwendungen zu.',pairs:[['Schnittlauch','Quark, Eierspeisen, Kräuterbutter','🌿'],['Estragon','Sauce Béarnaise, Geflügel, helle Saucen','🌿'],['Petersilie','Suppen, Fonds, Garnitur, Kräuterbutter','🌿'],['Minze','Joghurt, Couscous, Lamm, Tee','🌿']],explain:'Klassische Krautverwendungen zu kennen hilft beim schnellen Abschmecken und bei der Menüplanung.',hint:'Béarnaise = Estragon; Quark und Rührei = Schnittlauch.',knowledge:{title:'Kräuterkunde · Anwendungen',text:'Nicht jedes Kraut passt zu jeder Speise. Typische Anwendungen orientieren sich am Aroma: feinwürzig, anisartig, zwiebelig oder kühlend.',facts:['Estragon: Béarnaise','Schnittlauch: Quark & Ei','Minze: Joghurt & Lamm']}});
add({rank:3,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Estragon oder Kerbel?',photo:'assets/real/tarragon_bundle.svg',prompt:'Welche Aussage passt fachlich am besten zu Estragon?',scenes:[['Er passt klassisch zu Béarnaise, Geflügel und hellen Saucen und bringt ein leicht anisartiges Aroma mit.','🌿',1],['Er ist vor allem das Standardkraut für Sauerkraut, Wildmarinaden und Wacholdergerichte.','🍖',0],['Er wird fast nur für süße Grütze und Weihnachtsgebäck verwendet.','🍰',0],['Er ist ein scharfes Wurzelgewürz ähnlich Meerrettich.','🌶️',0]],explain:'Estragon hat ein elegantes, anisartiges Aroma und ist besonders in der klassischen Küche wichtig – vor allem für Béarnaise.',hint:'Denke an Béarnaise und feine helle Saucen.',knowledge:{title:'Kräuterkunde · Estragon',text:'Estragon gehört zu den klassischen Kräutern der französischen Küche. Sein Aroma ist feinwürzig und leicht anisartig; es passt besonders gut zu Béarnaise, Geflügel und hellen Ragouts.',facts:['leicht anisartig','wichtig in der klassischen Küche','typisch: Sauce Béarnaise']}});
add({rank:0,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Gewürzkunde',title:'Muskat erkennen',photo:'assets/real/spice_nutmeg.svg',prompt:'Wofür eignet sich Muskat besonders gut?',scenes:[['Kartoffelpüree, Spinat und Béchamel','🧂',1],['Tomateneis und Limonade','🍅',0],['Heringssalat mit Curry ausschließlich','🐟',0],['Sushi-Reis und Wasabi','🍚',0]],explain:'Muskat ist klassisch bei Kartoffelpüree, Spinat und Béchamel. Es wird sparsam und frisch gerieben eingesetzt.',hint:'Ein kleines bisschen reicht oft schon aus.',knowledge:{title:'Gewürzkunde · Muskat',text:'Muskat bringt eine warme, würzige Tiefe in milde, cremige Speisen. Klassische Partner sind Kartoffeln, Spinat, Blumenkohl und helle Saucen.',facts:['sparsam dosieren','klassisch zu Püree und Spinat','gut in Béchamel']}});
add({rank:1,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Gewürzkunde',title:'Paprika edelsüß erkennen',photo:'assets/real/spice_paprika.svg',prompt:'Welche Verwendung ist für Paprika edelsüß fachlich am naheliegendsten?',scenes:[['Paprikarahmsauce, Gulasch und Schmorgerichte','🧂',1],['Crème brûlée und Zitronensorbet','🍋',0],['Sushi und Algensalat','🍣',0],['Vanillecreme und Panna cotta','🍮',0]],explain:'Paprika edelsüß gibt Farbe und milde Fruchtigkeit. Typisch sind Gulasch, Paprikarahmsauce und Schmorgerichte.',hint:'Denke an rote Sauce und Schmorgerichte.',knowledge:{title:'Gewürzkunde · Paprika',text:'Paprika edelsüß bringt eine milde Fruchtigkeit und schöne rote Farbe. Es wird gerne in Schmorgerichten, Paprikarahmsaucen, Würzmischungen und Gemüsegerichten verwendet.',facts:['mild-fruchtig','gibt rote Farbe','nicht zu heiß verbrennen lassen']}});
add({rank:2,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Gewürzkunde',title:'Safran erkennen',photo:'assets/real/spice_saffron.svg',prompt:'Zu welchen klassischen Gerichten passt Safran besonders gut?',scenes:[['Paella, Risotto alla Milanese und feine Fischsuppen','🧂',1],['Sauerbraten, Rotkohl und Grünkohl','🥬',0],['Bouillabaisse und Sauce Béarnaise','🥣',0],['Kartoffelpuffer mit Apfelmus ausschließlich','🥔',0]],explain:'Safran ist teuer, färbend und edel im Aroma. Typisch sind Paella, Risotto alla Milanese und feine Fischzubereitungen.',hint:'Gesucht ist das gelb färbende Edelgewürz.',knowledge:{title:'Gewürzkunde · Safran',text:'Safran färbt Speisen goldgelb und verleiht ein feines, charakteristisches Aroma. Er wird sparsam eingesetzt und gern in Reisgerichten, Fischsuppen und edlen Saucen verwendet.',facts:['färbt goldgelb','sparsam dosieren','typisch: Paella · Risotto Milanese']}});
add({rank:2,profession:'Küche',type:'match',cat:'Kräuter & Gewürze',section:'Gewürzkunde',title:'Gewürze und typische Eignung',prompt:'Ordne die Gewürze ihrer typischen Verwendung zu.',pairs:[['Zimt','Milchreis, Kompott, winterliche Desserts','🧂'],['Kreuzkümmel','Chili, Couscous, Hummus, orientalische Küche','🧂'],['Wacholder','Wild, Sauerkraut, Marinaden','🧂'],['Muskat','Püree, Spinat, helle Saucen','🧂']],explain:'Gewürze prägen die Stilrichtung einer Speise oft sehr deutlich. Gerade Zimt, Kreuzkümmel und Wacholder sollten sicher erkannt werden.',hint:'Orientalisch = Kreuzkümmel; Wild und Sauerkraut = Wacholder.',knowledge:{title:'Gewürzkunde · Anwendungen',text:'Gewürze werden nicht nur nach Schärfe, sondern vor allem nach Aromaprofil eingesetzt. So prägen sie ganze Küchenstile – von orientalisch über klassisch deutsch bis süß-winterlich.',facts:['Zimt: süß-warm','Kreuzkümmel: orientalisch-erdig','Wacholder: Wild & Sauerkraut']}});
add({rank:3,profession:'Küche',type:'scene',cat:'Kräuter & Gewürze',section:'Gewürzkunde',title:'Kreuzkümmel oder Kümmel?',photo:'assets/real/spice_cumin.svg',prompt:'Welche Aussage trifft auf Kreuzkümmel am ehesten zu?',scenes:[['Er passt gut zu Chili, Couscous, Hummus und vielen orientalischen oder mexikanischen Gerichten.','🧂',1],['Er wird in Mitteleuropa klassisch vor allem für Brot, Kohl und Schweinebraten verwendet.','🥖',0],['Er ist das klassische Gewürz für Milchreis und Grießbrei.','🍚',0],['Er dient hauptsächlich als Süßungsmittel in Desserts.','🍮',0]],explain:'Kreuzkümmel ist nicht dasselbe wie Kümmel. Sein erdig-warmes Aroma ist typisch für orientalische, indische und mexikanische Gerichte.',hint:'Denk an Hummus, Falafel oder Chili con Carne.',knowledge:{title:'Gewürzkunde · Kreuzkümmel',text:'Kreuzkümmel besitzt ein warmes, erdiges Aroma und ist international sehr verbreitet. Typische Anwendungen sind Hummus, Couscous, Falafel, Curry- und Chili-Gerichte.',facts:['nicht mit Kümmel verwechseln','typisch für orientalische Küche','passt zu Hülsenfrüchten und Lamm']}});
add({rank:4,profession:'Küche',type:'multi',cat:'Kräuter & Gewürze',section:'Kräuterkunde',title:'Fines Herbes',prompt:'Welche 4 Kräuter zählen klassisch zu den feinen französischen Kräutern „fines herbes“?',dish:'🌿',caption:'Feinwürzige Kräutermischung',inside:['klassische Küche'],choices:[c('Kerbel','🌿',1),c('Schnittlauch','🌿',1),c('Petersilie','🌿',1),c('Estragon','🌿',1),c('Rosmarin','🌿',0),c('Salbei','🌿',0),c('Dill','🌿',0)],need:4,answer:['Kerbel','Schnittlauch','Petersilie','Estragon'],explain:'Fines Herbes bestehen klassisch aus Kerbel, Schnittlauch, Petersilie und Estragon. Die Kräuter werden fein und eher frisch eingesetzt.',hint:'Gesucht sind die zarten, feinwürzigen Vertreter – nicht die kräftig-harzigen.',knowledge:{title:'Kräuterkunde · Fines Herbes',text:'Fines Herbes ist eine klassische, feinwürzige Kräuterkombination der französischen Küche. Sie eignet sich für Eierspeisen, helle Saucen, feine Fischgerichte und zarte Geflügelzubereitungen.',facts:['Kerbel · Schnittlauch · Petersilie · Estragon','eher feinwürzig','frisch zugeben']}});
