add({rank:1,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:2,title:'Scholle oder Seezunge?',prompt:'Welche Aussage beschreibt beide Fischarten fachlich richtig?',scenes:[['Beide sind Plattfische und liefern bei klassischer Filetierung vier Filets','🐟',1],['Beide sind Rundfische mit zwei Hauptfilets','🐟',0],['Nur die Scholle ist ein Plattfisch; Seezunge zählt zu den Rundfischen','🐟',0],['Beide werden fachlich wie Krustentiere zerlegt','🦐',0]],explain:'Scholle und Seezunge gehören zu den Plattfischen. Durch ihre Körperform werden typischerweise vier Filets ausgelöst.',hint:'Achte auf die Körperform, nicht auf die Größe.',knowledge:{title:'Fischkunde · Plattfische',text:'Scholle und Seezunge sind typische Plattfische. Ihre Anatomie unterscheidet sich deutlich vom Rundfisch und beeinflusst die Filetiertechnik.',facts:['Plattfisch','vier Filets','andere Schnittführung als beim Rundfisch']}});
add({rank:2,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:3,title:'Fischhaut knusprig braten',prompt:'Welche Vorgehensweise unterstützt eine knusprige Fischhaut am besten?',scenes:[['Haut gut trocknen, passend würzen, mit Hautseite auf ausreichend heißer Fläche starten und anfangs Kontakt halten','🍳',1],['Fischhaut vor dem Braten stark wässern und in kalter Pfanne starten','💧',0],['Die Haut mit viel Sauce bedecken und nur dämpfen','🥣',0],['Hautseite sofort nach dem Einlegen ständig wenden','🔁',0]],explain:'Trockene Haut und guter Pfannenkontakt fördern Bräunung und Knusprigkeit. Zu viel Feuchtigkeit behindert diesen Effekt.',hint:'Feuchtigkeit ist der Gegner der knusprigen Oberfläche.'});
add({rank:2,profession:'Küche',type:'multi',cat:'Warenkunde',section:'Fischkunde',difficulty:3,title:'Fischfilet kontrollieren',prompt:'Welche 3 Kontrollen sind vor dem Garen eines Fischfilets besonders sinnvoll?',dish:'🐟',caption:'Mise en place',inside:['Fischfilet'],choices:[c('Gräten kontrollieren','🦴',1),c('Portionsstärke prüfen','📏',1),c('Oberfläche auf Sauberkeit und Feuchtigkeit prüfen','💧',1),c('Panierung grundsätzlich aufbringen','🌾',0),c('Filet immer vorher einfrieren','❄️',0),c('Haut bei jedem Gericht zwingend entfernen','🔪',0)],need:3,answer:['Gräten kontrollieren','Portionsstärke prüfen','Oberfläche auf Sauberkeit und Feuchtigkeit prüfen'],explain:'Vor dem Garen helfen Grätenkontrolle, gleichmäßige Portionierung und ein sauber vorbereiteter Zustand dabei, ein reproduzierbares Ergebnis zu erreichen.',hint:'Kontrolliere Struktur, Portion und Oberfläche.'});
add({rank:3,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:4,title:'Fischfond nicht zu kräftig rösten',prompt:'Warum werden Karkassen für einen klassischen hellen Fischfond in der Regel nicht so stark geröstet wie Knochen für einen braunen Kalbsfond?',scenes:[['Weil ein heller Fischfond eine feine, frische Aromatik und helle Farbe behalten soll','🥣',1],['Weil Fischkarkassen überhaupt keine Aromen abgeben können','🐟',0],['Weil Rösten nur bei Geflügel erlaubt ist','🍗',0],['Weil jeder Fischfond grundsätzlich kalt serviert wird','❄️',0]],explain:'Ein heller Fischfond soll fein, frisch und relativ hell bleiben. Starkes Rösten würde Farbe und Aromaprofil deutlich verändern.',hint:'Vergleiche die Zielrichtung von hellem Fischfond und braunem Kalbsfond.'});
add({rank:3,profession:'Küche',type:'match',cat:'Warenkunde',section:'Fischkunde',difficulty:4,title:'Fisch und Saucencharakter',prompt:'Ordne die Kombination fachlich möglichst schlüssig zu.',pairs:[['Seezunge','feine Butter- oder Weißweinsauce','🐟'],['Lachs','leichte Säure, Kräuter oder Senfkomponente','🐟'],['Kabeljau','helle Sauce, Kräuter oder Tomatenfond','🐟'],['Räucherfisch','frische Meerrettich- oder Senfkomponente','🐟']],explain:'Saucen sollten Fettgehalt, Eigengeschmack und Textur des Fisches unterstützen, nicht überdecken.',hint:'Je feiner der Fisch, desto zurückhaltender sollte die Sauce sein.'});
add({rank:4,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:5,title:'Fischportionen gleichmäßig garen',prompt:'Vier Lachsportionen sind unterschiedlich dick. Was ist für ein gleichmäßiges Garergebnis am sinnvollsten?',scenes:[['Portionen nach Stärke sortieren bzw. anpassen und Garzeit beziehungsweise Entnahmezeit daran ausrichten','🐟',1],['Alle Portionen unabhängig von Dicke exakt gleich lang garen','⏱️',0],['Nur die dünnste Portion messen und daraus alle anderen ableiten','🌡️',0],['Dickere Stücke grundsätzlich stärker salzen statt die Garung anzupassen','🧂',0]],explain:'Portionsstärke beeinflusst die Garzeit deutlich. Einheitliche Größen oder abgestufte Entnahmezeiten erhöhen die Reproduzierbarkeit.',hint:'Unterschiedliche Dicke verlangt unterschiedliche Prozessführung.'});
add({rank:4,profession:'Küche',type:'multi',cat:'Warenkunde',section:'Fischkunde',difficulty:5,title:'Fischkarkasse sinnvoll nutzen',prompt:'Welche 3 Punkte sprechen für eine fachgerechte Nutzung geeigneter Fischkarkassen?',dish:'🐟',caption:'Ausbeute & Fond',inside:['Karkassen'],choices:[c('Für Fischfond verwenden','🥣',1),c('Sauber und zeitnah weiterverarbeiten','⏱️',1),c('Art und Aromastärke des Fisches berücksichtigen','🐟',1),c('Grundsätzlich mit brauner Demi-glace mischen','🥘',0),c('Unabhängig von Frische lange warm lagern','♨️',0),c('Jede Fischart gleich stark rösten','🔥',0)],need:3,answer:['Für Fischfond verwenden','Sauber und zeitnah weiterverarbeiten','Art und Aromastärke des Fisches berücksichtigen'],explain:'Karkassen erhöhen die Ausbeute, müssen aber sauber, zeitnah und passend zur gewünschten Fondart eingesetzt werden.',hint:'Ausbeute ist nur sinnvoll, wenn Qualität und Aromatik stimmen.'});
add({rank:5,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:6,title:'Fischkarte wirtschaftlich planen',prompt:'Ein hochwertiger Fisch hat einen hohen Einkaufspreis, aber sehr gute Ausbeute. Welche Bewertung ist fachlich am sinnvollsten?',scenes:[['Einkaufspreis, nutzbare Ausbeute, Portionsgröße, Verkaufspreis und Verderbrisiko gemeinsam kalkulieren','📊',1],['Nur den Kilopreis vergleichen und die Ausbeute ignorieren','💶',0],['Hoher Einkaufspreis bedeutet automatisch schlechten Deckungsbeitrag','📉',0],['Ausbeute spielt nur bei Fleisch, nicht bei Fisch eine Rolle','🐟',0]],explain:'Für die Wirtschaftlichkeit zählt nicht nur der Einkaufspreis, sondern der tatsächlich nutzbare Anteil und die daraus erzielbare Portionierung.',hint:'Kilopreis allein sagt noch nichts über die Kosten pro verkaufsfähiger Portion.'});
add({rank:5,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:6,title:'Fischgarung im Bankett',prompt:'Bei 80 Fischportionen droht Nachgarung während der Ausgabe. Welche Strategie ist am professionellsten?',scenes:[['Garprozess, Portionsstärke, Chargengröße, Haltezeit und Ausgabe so takten, dass die Zielgarung erst möglichst nah am Pass erreicht wird','📋',1],['Alle Portionen früh vollständig durchgaren und lange heiß halten','♨️',0],['Die Garzeit pauschal verlängern, damit keine Portion roh wirkt','⏱️',0],['Nur mehr Sauce bereitstellen, um trockenere Portionen auszugleichen','🥣',0]],explain:'Bei Fisch ist Nachgarung besonders relevant. Chargierung und Ausgabe müssen deshalb enger getaktet werden als bei vielen robusteren Produkten.',hint:'Plane rückwärts vom Pass und berücksichtige Nachgarung.'});
add({rank:6,profession:'Küche',type:'scene',cat:'Warenkunde',section:'Fischkunde',difficulty:7,title:'Fischsortiment – Lieferant wechseln?',prompt:'Ein günstigerer Lieferant bietet denselben Fisch an, aber mit schwankender Sortierung und Ausbeute. Welche Entscheidung ist auf Leitungsebene am belastbarsten?',scenes:[['Musterlieferungen prüfen und Preis, Qualität, Kalibrierung, Ausbeute, Reklamationsquote und Prozessstabilität vergleichen','📊',1],['Allein wegen des niedrigeren Kilopreises sofort vollständig wechseln','💶',0],['Nur die Optik einer einzelnen Musterkiste bewerten','👁️',0],['Ausbeute und Reklamationen ignorieren, solange die Rechnung günstiger ist','🧾',0]],explain:'Lieferantenentscheidungen müssen Gesamtkosten und Prozessstabilität betrachten. Ein niedriger Kilopreis kann durch schwache Ausbeute oder Reklamationen aufgezehrt werden.',hint:'Bewerte nicht den Preis isoliert, sondern die gesamte Prozessleistung.'});
add({rank:6,profession:'Küche',type:'match',cat:'Warenkunde',section:'Fischkunde',difficulty:7,title:'Fischkunde – Leitungsebene',prompt:'Ordne das Problem der sinnvollsten ersten Steuerungsmaßnahme zu.',pairs:[['Schwankende Portionsausbeute','Kalibrierung, Zuschnitt und Lieferqualität prüfen','📏'],['Trockener Fisch am Pass','Garprozess, Nachgarung und Haltezeit analysieren','🌡️'],['Starke Fondschwankung','Karkassenmix, Ansatzmenge und Kochzeit standardisieren','🥣'],['Hohe Abschrift','Bestellmenge, Lagerdauer und Absatzdaten abgleichen','📊']],explain:'Auf Leitungsebene werden Fehler nicht einzeln kaschiert, sondern über messbare Prozessursachen gesteuert.',hint:'Ordne jeweils die Ursache, nicht nur das sichtbare Symptom.'});
