add({rank:2,profession:'Küche',type:'scene',cat:'Prüfungsvorbereitung',section:'Wirtschafts- und Sozialkunde',examArea:'Wirtschafts- und Sozialkunde',difficulty:3,title:'Ausbildungsvertrag',prompt:'Welche Aussage zum Ausbildungsverhältnis ist fachlich am treffendsten?',scenes:[['Ausbildende und Auszubildende haben gegenseitige Rechte und Pflichten; Ausbildungsziel und Ausbildungsnachweis gehören zum geregelten Ausbildungsverhältnis.','📄',1],['Nur der Ausbildungsbetrieb hat Pflichten; Auszubildende haben keine.','📄',0],['Ein Ausbildungsvertrag regelt ausschließlich die Höhe des Trinkgelds.','💶',0],['Berufsschule und betriebliche Ausbildung stehen grundsätzlich ohne Zusammenhang nebeneinander.','🏫',0]],explain:'Die Berufsausbildung ist ein geregeltes Rechtsverhältnis mit Pflichten auf beiden Seiten. Für Prüfungsfragen ist wichtig, typische Rechte, Pflichten und betriebliche Zusammenhänge unterscheiden zu können.',hint:'Denke an den geregelten Ausbildungszweck und gegenseitige Pflichten.'});
