add({rank:2,profession:'Küche',type:'scene',cat:'Prüfungsvorbereitung',section:'Wirtschafts- und Sozialkunde',examArea:'Wirtschafts- und Sozialkunde',difficulty:3,title:'Sozialversicherung',prompt:'Welche Aussage beschreibt die gesetzliche Sozialversicherung am besten?',scenes:[['Sie sichert typische Lebensrisiken wie Krankheit, Pflegebedürftigkeit, Arbeitslosigkeit, Arbeitsunfälle und Alter über verschiedene Zweige ab.','🛡️',1],['Sie besteht nur aus einer privaten Haftpflichtversicherung.','🛡️',0],['Sie betrifft ausschließlich Selbstständige in der Gastronomie.','🏢',0],['Sie ersetzt sämtliche Steuern eines Unternehmens.','🧾',0]],explain:'Zu den klassischen Zweigen gehören Kranken-, Pflege-, Renten-, Arbeitslosen- und Unfallversicherung.',hint:'Mehrere gesetzliche Sicherungssysteme gehören zusammen.'});
add({rank:3,profession:'Küche',type:'scene',cat:'Prüfungsvorbereitung',section:'Produkte, Lagerhaltung und Warenwirtschaft',examArea:'Produkte, Lagerhaltung und Warenwirtschaft',difficulty:4,title:'Angebotsvergleich',prompt:'Zwei Lieferanten bieten denselben Artikel an. Lieferant A ist pro kg günstiger, Lieferant B hat deutlich bessere Ausbeute und konstante Qualität. Was ist fachlich am sinnvollsten?',scenes:[['Gesamtkosten pro nutzbarer Portion, Qualität, Lieferzuverlässigkeit und Ausbeute vergleichen.','📊',1],['Immer nur den niedrigsten Kilopreis wählen.','💶',0],['Nur Einkaufspreis und Zahlungsziel vergleichen, ohne Ausbeute und Qualitätskonstanz einzubeziehen.','📦',0],['Lieferqualität berücksichtigen, aber Ausbeute grundsätzlich nicht in Kosten je Portion einrechnen.','⚖️',0]],explain:'Warenwirtschaftliche Entscheidungen beruhen nicht nur auf dem Einkaufspreis. Nutzbare Ausbeute, Qualität, Lieferfähigkeit und Reklamationsrisiko beeinflussen die tatsächlichen Kosten.',hint:'Nicht Einkaufspreis mit Kosten pro verkaufsfähiger Portion verwechseln.'});
add({rank:3,profession:'Küche',type:'scene',cat:'Prüfungsvorbereitung',section:'Technologie, Gästeinformation und Arbeiten im Team',examArea:'Technologie, Gästeinformation und Arbeiten im Team',difficulty:4,title:'Allergenberatung',prompt:'Ein Gast fragt wegen einer Allergie nach einem Gericht. Welche Reaktion ist am professionellsten?',scenes:[['Rezeptur und betriebliche Allergeninformation prüfen, Kreuzkontakt berücksichtigen und nur gesicherte Angaben machen.','ℹ️',1],['Nur die aktuelle Speisekarte lesen und auf frühere Rezepturstände vertrauen.','📋',0],['Eine sehr kleine Probierportion anbieten, wenn der Gast zustimmt.','🥄',0],['Nur die Hauptzutaten prüfen und mögliche Kreuzkontakte außer Betracht lassen.','ℹ️',0]],explain:'Gästesicherheit verlangt gesicherte Informationen und Aufmerksamkeit für möglichen Kreuzkontakt.',hint:'Nur verifizierte Informationen weitergeben.'});
add({rank:3,profession:'Küche',type:'scene',cat:'Prüfungsvorbereitung',section:'Planen, Zubereiten und Präsentieren eines Drei-Gänge-Menüs',examArea:'Planen, Zubereiten und Präsentieren eines Drei-Gänge-Menüs',difficulty:4,title:'Arbeitsablaufplan',prompt:'Welche Planung ist für ein Drei-Gänge-Menü am belastbarsten?',scenes:[['Rückwärts vom Ausgabezeitpunkt planen, kritische Gar- und Ruhezeiten markieren und parallele Arbeitsschritte koordinieren.','📋',1],['Alle Komponenten der Reihe nach kochen, unabhängig von Garzeit und Ausgabe.','⏱️',0],['Nur den Hauptgang planen; Vor- und Nachspeise spontan entscheiden.','🍽️',0],['Zeitpuffer grundsätzlich vermeiden, weil sie unwirtschaftlich sind.','⌛',0]],explain:'Ein guter Arbeitsablaufplan verbindet Reihenfolge, Parallelisierung, kritische Zeitpunkte, Hygiene und Ausgabe.',hint:'Plane vom Pass rückwärts.'});
