add({rank:3,profession:'Küche',type:'scene',cat:'Praxisentscheidung',section:'Saucen',difficulty:4,didaktik:'next-step',competencyStage:'Anwenden',title:'Hollandaise · Was jetzt?',prompt:'Die Sauce Hollandaise beginnt beim Arbeiten sichtbar zu gerinnen. Was ist als nächste fachlich sinnvolle Reaktion?',scenes:[['Direkte Hitze stoppen, die Sauce kontrolliert abkühlen bzw. mit wenig Flüssigkeit stabilisieren und anschließend vorsichtig neu emulgieren.','🥣',1],['Die Hitze stark erhöhen und kräftig weiterkochen.','🔥',0],['Sofort Mehl einrühren und zehn Minuten kochen.','🌾',0],['Die Sauce mit kaltem Öl auffüllen, bis sie wieder glatt wirkt.','🫗',0]],explain:'Bei einer instabilen warmen Emulsion wird starke Hitze vermieden. Ziel ist, die Emulsion kontrolliert wieder aufzubauen.',hint:'Nicht mehr Hitze – die Emulsion muss stabilisiert werden.',knowledge:{title:'Transfer · Hollandaise',text:'Bei Emulsionsproblemen ist Ursachenverständnis wichtiger als ein starres Rezept. Temperatur, Wasserphase und Fettzugabe müssen wieder in ein stabiles Verhältnis gebracht werden.',facts:['direkte Hitze stoppen','Emulsion stabilisieren','kontrolliert weiterarbeiten']}});

add({rank:3,profession:'Küche',type:'errorhunt',cat:'Fehlerjagd',section:'Internationale Küche',difficulty:4,didaktik:'error-analysis',competencyStage:'Fehler finden',title:'Carbonara · Fehlerjagd',prompt:'Finde die 3 Punkte, die nicht zur in FUTURA verwendeten klassischen römischen Grundform passen.',need:3,spots:[['Sahne als Basis der Sauce','🥛',1,'Die Cremigkeit entsteht in dieser Grundform aus Ei, Käse und Pastawasser.'],['Kochschinken statt Guanciale','🍖',1,'Die klassische Grundform verwendet Guanciale.'],['Eiermasse kräftig aufkochen','🔥',1,'Zu starke Hitze lässt das Ei unerwünscht stocken.'],['Pecorino Romano verwenden','🧀',0,'Pecorino Romano gehört zur Grundform.'],['Schwarzen Pfeffer frisch einsetzen','⚫',0,'Schwarzer Pfeffer ist charakteristisch.'],['Pastawasser zur Emulsion nutzen','💧',0,'Stärkehaltiges Pastawasser unterstützt die cremige Emulsion.']],explain:'Die drei Fehler sind Sahne als Saucenbasis, Kochschinken und das starke Aufkochen der Eiermasse.',hint:'Prüfe Fettkomponente, Bindung und Temperatur.',knowledge:{title:'Fehleranalyse · Carbonara',text:'Fehlerjagd trainiert nicht nur das Wiedererkennen eines Rezeptes, sondern das fachliche Unterscheiden plausibler Varianten.',facts:['Guanciale','Ei + Käse + Pastawasser','keine starke direkte Hitze']}});

add({rank:4,profession:'Küche',type:'sequence',cat:'Arbeitsablauf',section:'Internationale Küche',difficulty:5,didaktik:'workflow',competencyStage:'Anwenden',title:'Ossobuco · Arbeitsfolge',prompt:'Ordne den fachlich schlüssigen Grundablauf für ein geschmortes Ossobuco.',items:['Kalbshaxenscheiben vorbereiten und würzen','Leicht mehlieren','Kräftig anbraten','Röstgemüse bzw. Ansatz aufbauen','Ablöschen und Schmorfond ansetzen','Schonend schmoren','Gremolata frisch zum Abschluss einsetzen'],answer:['Kalbshaxenscheiben vorbereiten und würzen','Leicht mehlieren','Kräftig anbraten','Röstgemüse bzw. Ansatz aufbauen','Ablöschen und Schmorfond ansetzen','Schonend schmoren','Gremolata frisch zum Abschluss einsetzen'],explain:'Die Reihenfolge verbindet Vorbereitung, Röstaromen, Schmoransatz, langsames Garen und den frischen Abschluss.',hint:'Erst vorbereiten und rösten, dann Flüssigkeit und Zeit – Frische zuletzt.',knowledge:{title:'Workflow · Ossobuco',text:'Das Sortieren vollständiger Arbeitsabläufe trainiert Prozesswissen statt einzelner Fakten.',facts:['Röstaromen vor dem Schmoren','Schmorfond aufbauen','Gremolata zum Schluss']}});

add({rank:4,profession:'Küche',type:'scene',cat:'Transfer',section:'Warenkunde',difficulty:5,didaktik:'transfer',competencyStage:'Transfer',title:'Hummer · weicher Panzer',prompt:'Ein Hummer hat einen auffallend weichen, noch wenig ausgehärteten Panzer. Welche fachliche Erklärung ist am plausibelsten?',scenes:[['Er hat sich vergleichsweise kürzlich gehäutet; der neue Panzer ist noch nicht vollständig ausgehärtet.','🦞',1],['Das Tier hat grundsätzlich keinen Panzer ausgebildet.','❌',0],['Ein weicher Panzer beweist, dass der Hummer gekocht wurde.','🔥',0],['Die Panzerhärte hängt ausschließlich von der Tageszeit ab.','🕒',0]],explain:'Nach der Häutung ist der neue Panzer zunächst weich und härtet anschließend aus.',hint:'Verknüpfe die Warenkunde mit dem Häutungszyklus.'});

add({rank:4,profession:'Küche',type:'explain',cat:'Erklärfrage',section:'Internationale Küche',difficulty:5,didaktik:'self-explanation',competencyStage:'Begründen',examEligible:false,challenge:false,title:'Carbonara · Erklär es dem Azubi',prompt:'Ein Azubi sagt: „Für eine cremige Carbonara brauche ich Sahne und muss die Eiermasse aufkochen.“ Erkläre ihm fachlich, wie die Cremigkeit stattdessen entsteht.',explainInstruction:'Nenne die entscheidenden Zutaten und erkläre besonders die Bindung sowie den Umgang mit der Hitze.',rubric:{groups:[['guanciale'],['ei','eigelb'],['pecorino'],['pastawasser','nudelwasser','stärke','emulsion','emulgieren'],['nicht aufkochen','nicht kochen','nicht stocken','rührei','restwärme','abseits der hitze'],['keine sahne','ohne sahne']],minGroups:4},modelAnswer:'Guanciale wird ausgelassen. Ei bzw. Eigelb wird mit Pecorino verbunden. Die heiße Pasta und etwas stärkehaltiges Pastawasser erzeugen abseits starker direkter Hitze eine cremige Emulsion. Die Eiermasse darf nicht zu Rührei stocken; Sahne ist für diese Grundform nicht erforderlich.',explain:'Die Cremigkeit entsteht durch die Emulsion aus Ei, Pecorino, Fett und Pastawasser bei kontrollierter Temperatur.',hint:'Bindung + Temperatur + klassische Zutaten.',knowledge:{title:'Selbsterklärung · Carbonara',text:'Wer einen Ablauf in eigenen Worten erklären kann, zeigt mehr als Wiedererkennen. Entscheidend sind Bindungsprinzip und Temperaturführung.',facts:['Ei/Eigelb + Pecorino','Pastawasser unterstützt Emulsion','keine starke direkte Hitze']}});

add({rank:3,profession:'Küche',type:'explain',cat:'Erklärfrage',section:'Warenkunde',difficulty:4,didaktik:'self-explanation',competencyStage:'Unterscheiden',examEligible:false,challenge:false,title:'Hase und Kaninchen · Unterschiede erklären',prompt:'Erkläre einem Auszubildenden mindestens drei fachlich sinnvolle Unterschiede zwischen Hase und Kaninchen.',explainInstruction:'Du kannst Körperbau, Lebensweise und küchenfachliche Eigenschaften miteinander vergleichen.',rubric:{groups:[['hase größer','hase grosser','größer','großer','langbein','lange hinterläufe','lange hinterlaufe'],['kaninchen bau','baue','bauten','unterirdisch'],['hase einzel','einzelgänger','einzelganger','sasse','mulde'],['hase dunkler','hase kräftiger','hase kraftiger','kräftiger geschmack','kraftiger geschmack'],['kaninchen heller','kaninchen milder','milder']],minGroups:3},modelAnswer:'Hasen sind typischerweise größer und langbeiniger und ruhen oberirdisch in einer Sasse; Kaninchen leben typischerweise in unterirdischen Bauen. Küchenfachlich ist Hasenfleisch meist dunkler und kräftiger, Kaninchenfleisch heller und milder.',explain:'Hase und Kaninchen unterscheiden sich in Körperbau, Lebensweise und typischen Fleischeigenschaften.',hint:'Körperbau · Bau/Sasse · Fleischcharakter.'});

add({rank:5,profession:'Küche',type:'scene',cat:'Meister-Fallprüfung',section:'Bankett & Küchenorganisation',difficulty:6,didaktik:'master-case',competencyStage:'Entscheiden',title:'Bankett · Drei Probleme gleichzeitig',prompt:'Kurz vor dem Service sind Sauce zu dünn, ein Braten verliert viel Saft und ein Gratin ist oben dunkel, innen aber noch fest. Was ist der beste erste Schritt?',scenes:[['Probleme priorisieren, Garzustände und Temperaturen prüfen, Ursachen je Komponente trennen und dann gezielt korrigieren.','🧭',1],['Alle drei Komponenten gemeinsam länger und heißer garen.','🔥',0],['Nur die Optik des Gratins korrigieren; die anderen Punkte ignorieren.','🎨',0],['Ohne Prüfung alle Speisen entsorgen.','🗑️',0]],explain:'Meisterniveau verlangt strukturierte Fehlerdiagnose: erst Zustand und Ursache erfassen, dann pro Komponente fachlich handeln.',hint:'Diagnose vor Aktion.',bonusCombo:{stage2:{title:'Bankett · Ursachenanalyse · 2×',prompt:'Welche 3 Prüfungen liefern jetzt besonders schnell verwertbare Informationen?',need:3,choices:[['Garzustand bzw. Kerntemperatur des Bratens prüfen','🌡️',1],['Konsistenz und Bindung der Sauce prüfen','🥣',1],['Gargrad der Kartoffeln im Gratin prüfen','🥔',1],['Nur die Tellerfarbe auswählen','🎨',0],['Musik im Gastraum ändern','🎵',0],['Alle Rezepturen ungeprüft verdoppeln','✖️',0]]},stage3:{title:'Bankett · Führungsentscheidung · 3×',prompt:'Welche Vorgehensweise beschreibt die beste Meisterentscheidung?',choices:[['Aufgaben klar verteilen, kritische Komponenten zuerst stabilisieren, Zeiten neu koordinieren und jede Korrektur vor Ausgabe prüfen.','👨‍🍳',1],['Alle Aufgaben selbst übernehmen und das Team ohne Informationen warten lassen.','🧍',0],['Service starten, obwohl Garzustände noch ungeprüft sind.','🚪',0],['Nur schneller arbeiten, ohne Prioritäten oder Qualitätskontrolle.','⏩',0]]}}});

add({rank:5,profession:'Küche',type:'scene',cat:'Transfer',section:'Saucen',difficulty:6,didaktik:'transfer',competencyStage:'Begründen',title:'Sauce bricht erneut',prompt:'Eine warme Emulsionssauce ist nach einer ersten Korrektur erneut instabil. Welche Schlussfolgerung ist fachlich am sinnvollsten?',scenes:[['Nicht nur erneut „retten“, sondern Temperatur, Verhältnis von Wasser- und Fettphase sowie Zugabegeschwindigkeit als Ursache systematisch prüfen.','🔎',1],['Mehr Hitze ist grundsätzlich immer die Lösung.','🔥',0],['Jede Emulsion wird ausschließlich durch Salz instabil.','🧂',0],['Die Ursache spielt keine Rolle, solange man weiter Fett zugibt.','🧈',0]],explain:'Transfer bedeutet, das Bindungsprinzip auf eine neue Situation anzuwenden und die Ursache systematisch zu prüfen.',hint:'Ursache statt Symptombehandlung.'});

