const shuffle=a=>{const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out};
let persistentQuestionHistory=window.KarriereStorage?.getQuestionHistorySync?.()||[];
function shuffledForQuestion(items,key,labelFn=x=>Array.isArray(x)?String(x[0]):String(x?.label||x?.name||x)){let out=shuffle(items);const prev=state.answerOrders?.[key];if(out.length>1&&prev){let sig=out.map(labelFn).join('|');for(let tries=0;tries<4&&sig===prev;tries++){out=shuffle(items);sig=out.map(labelFn).join('|')}}state.answerOrders=state.answerOrders||{};state.answerOrders[key]=out.map(labelFn).join('|');return out}
