function ensureQuickPlan(){if(!Array.isArray(state.quickPlan)||!state.quickPlan.length)state.quickPlan=makeQuickPlan();if(!Array.isArray(state.quickDone))state.quickDone=[];if(!Array.isArray(state.quickResults))state.quickResults=[]}
