function startTimer(q){stopTimer();state.timeLimit=timerSeconds(q);state.timeRemaining=state.timeLimit;if(!state.timeLimit){els.timeBonus.textContent='ohne Zeitdruck';return}updateTimer();timerHandle=setInterval(()=>{if(state.answered||state.paused)return;state.timeRemaining=Math.max(0,state.timeRemaining-1);updateTimer();if(state.timeRemaining<=0)stopTimer()},1000)}
