function render(q){els.area.innerHTML='';if(q.type==='multi')renderMulti(q);else if(q.type==='remove')renderRemove(q);else if(q.type==='sequence')renderSequence(q);else if(q.type==='scene')renderScene(q);else if(q.type==='match')renderMatch(q);else if(q.type==='plate')renderPlate(q);else if(q.type==='anatomy')renderAnatomy(q);else if(q.type==='errorhunt')renderErrorHunt(q);else if(q.type==='explain')window.KarriereDidaktik?.renderExplain?.(q,{area:els.area,state,resolve})}
function stageHTML(q){if(q.photo)return`<div class="realistic-stage"><img src="${q.photo}" alt="${q.title}"><div class="stage-caption"><strong>${q.title}</strong><small>${q.caption||q.cat}</small><div class="inside-list">${(q.inside||[]).map(x=>`<span class="inside-chip">${x}</span>`).join('')}</div></div></div>`;if(q.visual==='caprese')return`<div class="caprese-stage"><div class="caprese-plate"><i class="caprese-slice tomato" style="left:13%;top:18%"></i><i class="caprese-slice mozz" style="left:31%;top:25%"></i><i class="caprese-slice tomato" style="left:48%;top:34%"></i><i class="caprese-slice mozz" style="left:27%;top:51%"></i><i class="caprese-slice basil" style="left:52%;top:18%"></i><i class="caprese-slice basil" style="left:18%;top:56%"></i></div></div>`;return`<div class="professional-stage"><span class="skill-code">${rankIcons[state.rank]}</span><strong>${q.title}</strong><small>${q.caption||q.cat}</small><div class="inside-list">${(q.inside||[]).map(x=>`<span class="inside-chip">${x}</span>`).join('')}</div></div>`}
function createChoice(x){const b=document.createElement('button');b.className='choice-card'+(x[1]?'':' no-icon');b.dataset.name=x[0];b.innerHTML=`${x[1]?`<span class="choice-food-icon" aria-hidden="true">${x[1]}</span>`:''}<span class="choice-label">${x[0]}${x[3]?`<small class="choice-sub">${x[3]}</small>`:''}</span>`;return b}
function renderMulti(q){const w=document.createElement('div');w.className='dish-layout';w.innerHTML=stageHTML(q)+'<div class="choice-grid"></div>';const g=w.querySelector('.choice-grid');shuffledForQuestion(q.choices,`${q.id}:choices`,x=>x[0]).forEach(x=>{const b=createChoice(x);b.onclick=()=>{if(state.answered)return;b.classList.toggle('selected');const s=[...g.querySelectorAll('.selected')];if(s.length>q.need){b.classList.remove('selected');return}if(s.length===q.need){const names=s.map(e=>e.dataset.name),ok=q.answer.length===names.length&&q.answer.every(a=>names.includes(a));state.answered=true;[...g.children].forEach(e=>{if(q.answer.includes(e.dataset.name))e.classList.add('correct');else if(e.classList.contains('selected'))e.classList.add('wrong')});resolve(ok)}};g.appendChild(b)});els.area.appendChild(w)}
