function renderErrorHunt(q){const w=document.createElement('div');w.className='errorhunt-wrap';w.innerHTML=`<div class="errorhunt-scene"><div class="errorhunt-scene-head"><span>ARBEITSPLATZ-CHECK</span><b>${q.title}</b><small>${q.need} Fehler antippen</small></div><div class="errorhunt-grid"></div><div class="errorhunt-count">0 / ${q.need} markiert</div></div>`;const g=w.querySelector('.errorhunt-grid'),count=w.querySelector('.errorhunt-count');shuffledForQuestion(q.spots,`${q.id}:spots`,x=>x[0]).forEach(s=>{const b=document.createElement('button');b.className='error-spot';b.dataset.name=s[0];b.dataset.error=s[2]?'1':'0';b.innerHTML=`<span class="error-spot-icon" aria-hidden="true">${s[1]||'•'}</span><strong>${s[0]}</strong>`;b.onclick=()=>{if(state.answered)return;b.classList.toggle('selected');const selected=[...g.querySelectorAll('.selected')];if(selected.length>q.need){b.classList.remove('selected');return}count.textContent=`${selected.length} / ${q.need} markiert`;if(selected.length===q.need){const names=selected.map(e=>e.dataset.name),correctNames=q.spots.filter(x=>x[2]).map(x=>x[0]),ok=correctNames.every(x=>names.includes(x));state.answered=true;[...g.children].forEach(e=>{const isErr=e.dataset.error==='1';if(isErr)e.classList.add('correct');else if(e.classList.contains('selected'))e.classList.add('wrong')});count.textContent=ok?'Alle Fehler erkannt':`${selected.filter(e=>e.dataset.error==='1').length} von ${q.need} Fehlern erkannt`;resolve(ok)}};g.appendChild(b)});els.area.appendChild(w)}
function renderSequence(q){const w=document.createElement('div');w.className='sequence-wrap';w.innerHTML='<div class="sequence-panel"><h3>Verfügbare Karten</h3><div class="sequence-list bank"></div></div><div class="sequence-panel"><h3>Deine Reihenfolge</h3><div class="sequence-list target"></div></div>';const bank=w.querySelector('.bank');shuffledForQuestion(q.items,`${q.id}:sequence`,x=>String(x)).forEach(item=>{const b=document.createElement('button');b.className='seq-item';b.innerHTML=`<span>${item}</span><span>+</span>`;b.onclick=()=>{if(state.answered||b.classList.contains('used'))return;state.sequence.push(item);b.classList.add('used');drawTarget(q,w);if(state.sequence.length===q.answer.length){state.answered=true;resolve(state.sequence.every((x,i)=>x===q.answer[i]))}};bank.appendChild(b)});els.area.appendChild(w);drawTarget(q,w)}
