function renderScene(q){const wrap=document.createElement('div');wrap.className=q.photo?'scene-photo-layout':'scene-only-layout';if(q.photo)wrap.innerHTML=`<figure class="question-photo"><img src="${q.photo}" alt="${q.title}"><figcaption>${q.section||q.cat}</figcaption></figure><div class="scene-grid"></div>`;else wrap.innerHTML='<div class="scene-grid"></div>';const g=wrap.querySelector('.scene-grid');shuffledForQuestion(q.scenes,`${q.id}:scenes`,x=>x[0]).forEach(s=>{const b=document.createElement('button');b.className='service-card';b.dataset.name=s[0];b.innerHTML=`${s[1]?`<span class="service-art" aria-hidden="true">${s[1]}</span>`:''}<strong>${s[0]}</strong>`;b.onclick=()=>{if(state.answered)return;state.answered=true;b.classList.add(s[2]?'correct':'wrong');if(!s[2])[...g.children].forEach(e=>{const o=q.scenes.find(x=>x[0]===e.dataset.name);if(o?.[2])e.classList.add('correct')});resolve(!!s[2])};g.appendChild(b)});els.area.appendChild(wrap)}


function buildAnatomyPuzzle(q,host,onComplete,onProgress){host.innerHTML='';const wrap=document.createElement('div');wrap.className='anatomy-wrap';wrap.innerHTML=`<div class="anatomy-board"><img class="anatomy-silhouette" src="${q.photo}" alt="${q.title}">${q.parts.map((p,i)=>`<button class="anatomy-slot" data-idx="${i}" style="left:${p[2]}%;top:${p[3]}%;width:${p[4]||16}%;height:${p[5]||10}%;clip-path:${p[6]||'polygon(0 0,100% 0,100% 100%,0 100%)'}"><span>+</span></button>`).join('')}</div><div class="anatomy-help"><b>PUZZLE:</b> Teilstück auf die passende Stelle ziehen. Richtig = Einrasten. Falsch = Rücksprung.</div><div class="anatomy-parts"></div>`;const partsArea=wrap.querySelector('.anatomy-parts');let selectedPart=null,matched=0,wrong=0;const started=performance.now();const report=(part,ok)=>{const def=q.parts[Number(part?.dataset?.idx||0)]||[];onProgress?.({matched,total:q.parts.length,wrong,part:def[0]||'',usage:def[7]||'',correct:ok,responseMs:Math.round(performance.now()-started)})};const finish=(part,slot)=>{if(!part||!slot||slot.classList.contains('filled'))return;if(part.dataset.idx===slot.dataset.idx){const def=q.parts[Number(part.dataset.idx)]||[];slot.classList.add('filled','snap-in');slot.innerHTML=`<strong>${def[0]||part.dataset.name}</strong>`;part.classList.add('matched');part.disabled=true;part.style.visibility='hidden';part.classList.remove('selected','dragging');selectedPart=null;matched++;beep(true);report(part,true);if(matched===q.parts.length){wrap.classList.add('completed');onComplete?.(q,{matched,wrong,responseMs:Math.round(performance.now()-started)})}}else{wrong++;part.classList.add('wrong','snap-back');slot.classList.add('wrong');report(part,false);setTimeout(()=>{part.classList.remove('wrong','selected','dragging','snap-back');slot.classList.remove('wrong')},500);selectedPart=null;beep(false)}};shuffledForQuestion(q.parts,`${q.id}:anatomy`,x=>x[0]).forEach(p=>{const idx=q.parts.findIndex(a=>a[0]===p[0]);const b=document.createElement('button');b.className='anatomy-part';b.dataset.idx=String(idx);b.dataset.name=p[0];b.innerHTML=`<i class="anatomy-piece-shape" style="clip-path:${p[6]||'polygon(0 0,100% 0,100% 100%,0 100%)'}"></i><span><b>${p[0]}</b><small>${p[7]||'ziehen oder antippen'}</small></span>`;b.onclick=()=>{if(b.classList.contains('matched'))return;partsArea.querySelectorAll('.anatomy-part').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedPart=b};b.addEventListener('pointerdown',e=>{if(b.classList.contains('matched'))return;e.preventDefault();b.setPointerCapture?.(e.pointerId);b.classList.add('dragging');const ghost=document.createElement('div');ghost.className='anatomy-drag-ghost';ghost.innerHTML=`<i style="clip-path:${p[6]||'polygon(0 0,100% 0,100% 100%,0 100%)'}"></i><b>${p[0]}</b>`;document.body.appendChild(ghost);const move=ev=>{ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';wrap.querySelectorAll('.anatomy-slot').forEach(x=>x.classList.remove('drop-ready'));const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('.anatomy-slot');if(hit&&!hit.classList.contains('filled'))hit.classList.add('drop-ready')};const up=ev=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('.anatomy-slot');wrap.querySelectorAll('.anatomy-slot').forEach(x=>x.classList.remove('drop-ready'));ghost.remove();if(hit)finish(b,hit);else b.classList.remove('dragging')};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true})});partsArea.appendChild(b)});wrap.querySelectorAll('.anatomy-slot').forEach(slot=>slot.onclick=()=>{if(slot.classList.contains('filled')||!selectedPart)return;finish(selectedPart,slot)});host.appendChild(wrap)}
function renderAnatomy(q){const host=document.createElement('div');host.className='anatomy-game-host';buildAnatomyPuzzle(q,host,()=>{state.answered=true;resolve(true)});els.area.appendChild(host)}
function renderMatch(q){const pairs=q.pairs.map((p,i)=>({i,left:p[0],right:p[1],icon:p[2]||''}));const w=document.createElement('div');w.className='match-wrap'+(q.photo?' has-match-photo':'');w.innerHTML=`${q.photo?`<figure class="match-photo"><img src="${q.photo}" alt="${q.title}"></figure>`:''}<div class="drag-help">Links anfassen und direkt auf die passende Antwort rechts ziehen – Antippen funktioniert ebenfalls.</div><div class="match-col left"></div><div class="match-col right"></div>`;const l=w.querySelector('.left'),r=w.querySelector('.right');shuffledForQuestion(pairs,`${q.id}:matchL`,x=>x.left).forEach(p=>l.appendChild(matchCard('L',p)));shuffledForQuestion(pairs,`${q.id}:matchR`,x=>x.right).forEach(p=>r.appendChild(matchCard('R',p)));els.area.appendChild(w);enableMatchDrag(w)}
function matchCard(side,p){const b=document.createElement('button');b.className='match-card '+(side==='L'?'draggable-term':'drop-target');b.dataset.idx=p.i;b.dataset.side=side;b.innerHTML=`${p.icon&&side==='L'?`<span class="plate-choice-icon">${p.icon}</span> `:''}${side==='L'?p.left:p.right}`;b.onclick=()=>chooseMatch(b);return b}
function finishMatchPair(left,right){if(left.dataset.idx===right.dataset.idx){left.classList.remove('selected','dragging');right.classList.remove('selected','drop-ready');left.classList.add('matched');right.classList.add('matched');state.matched++;state.matchLeft=state.matchRight=null;if(state.matched===state.current.pairs.length){state.answered=true;resolve(true)}}else{left.classList.add('wrong');right.classList.add('wrong');setTimeout(()=>{left.classList.remove('wrong','selected','dragging');right.classList.remove('wrong','selected','drop-ready')},420);state.matchLeft=state.matchRight=null;beep(false)}}
function chooseMatch(b){if(state.answered||b.classList.contains('matched'))return;const side=b.dataset.side;document.querySelectorAll(`.match-col.${side==='L'?'left':'right'} .match-card`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');if(side==='L')state.matchLeft=b;else state.matchRight=b;if(state.matchLeft&&state.matchRight)finishMatchPair(state.matchLeft,state.matchRight)}
function enableMatchDrag(w){w.querySelectorAll('.draggable-term').forEach(card=>{card.addEventListener('pointerdown',e=>{if(state.answered||card.classList.contains('matched'))return;e.preventDefault();card.setPointerCapture?.(e.pointerId);card.classList.add('dragging');const ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=card.textContent.trim();document.body.appendChild(ghost);const move=ev=>{ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';w.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-ready'));const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('.drop-target');if(hit&&!hit.classList.contains('matched'))hit.classList.add('drop-ready')};const up=ev=>{card.releasePointerCapture?.(e.pointerId);card.removeEventListener('pointermove',move);card.removeEventListener('pointerup',up);card.removeEventListener('pointercancel',up);const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('.drop-target');ghost.remove();w.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-ready'));card.classList.remove('dragging');if(hit&&!hit.classList.contains('matched'))finishMatchPair(card,hit)};card.addEventListener('pointermove',move);card.addEventListener('pointerup',up);card.addEventListener('pointercancel',up);move(e)})})}
function renderPlate(q){const isCaprese=q.visual==='caprese'||/Tomate-Mozzarella|Caprese/i.test(q.title);const base=q.photo?`<div class="real-plate-photo"><img src="${q.photo}" alt="${q.title}"><span>${q.title}</span></div>`:isCaprese?`<div class="caprese-plate-v8" aria-label="Teller mit Tomate und Mozzarella"><i class="food-slice tomato" style="left:18%;top:22%"></i><i class="food-slice mozz" style="left:38%;top:28%"></i><i class="food-slice tomato" style="left:47%;top:48%"></i><i class="food-slice mozz" style="left:24%;top:54%"></i><span class="plate-caption-v8">Tomate · Mozzarella</span></div>`:`<div class="plate-rim"><div class="plate-center"><strong>${q.title}</strong><small>${q.caption||'Anrichten'}</small><div class="plate-slots">${Array.from({length:q.need},()=>'<span class="plate-slot">+</span>').join('')}</div></div></div>`;const w=document.createElement('div');w.className='plate-layout'+(isCaprese?' has-food-visual':'');w.innerHTML=`<div class="plate-stage">${base}</div><div class="choice-grid"></div>`;const g=w.querySelector('.choice-grid');shuffledForQuestion(q.choices,`${q.id}:plateChoices`,x=>x[0]).forEach(x=>{const b=createChoice(x);b.onclick=()=>{if(state.answered)return;b.classList.toggle('selected');const s=[...g.querySelectorAll('.selected')];if(s.length>q.need){b.classList.remove('selected');return}syncSlots(w,s,q);if(s.length===q.need){const names=s.map(e=>e.dataset.name),ok=q.answer.every(a=>names.includes(a));state.answered=true;[...g.children].forEach(e=>{if(q.answer.includes(e.dataset.name))e.classList.add('correct');else if(e.classList.contains('selected'))e.classList.add('wrong')});resolve(ok)}};g.appendChild(b)});els.area.appendChild(w)}
function syncSlots(w,s,q){const slots=[...w.querySelectorAll('.plate-slot')];slots.forEach((x,i)=>{x.textContent=s[i]?'✓':'+';x.classList.toggle('filled',!!s[i])});if(q&&(q.visual==='caprese'||/Tomate-Mozzarella|Caprese/i.test(q.title))){const plate=w.querySelector('.caprese-plate-v8');if(!plate)return;plate.querySelectorAll('.selected-food-extra').forEach(x=>x.remove());const names=s.map(x=>x.dataset.name);if(names.includes('Basilikum'))[['58%','18%'],['16%','48%'],['55%','64%']].forEach(([l,t])=>{const i=document.createElement('i');i.className='food-basil selected-food-extra';i.style.left=l;i.style.top=t;plate.appendChild(i)});if(names.includes('Olivenöl')){const i=document.createElement('i');i.className='food-oil selected-food-extra';i.style.left='46%';i.style.top='38%';plate.appendChild(i)}}}
function beep(ok=true){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=ok?720:180;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.start();o.stop(ctx.currentTime+.16)}catch(e){}}
function showKnowledge(q){const k=q.knowledge||{title:'Gut zu wissen',text:q.explain||'',facts:[]};els.knowledgeTitle.textContent=k.title||'Gut zu wissen';els.knowledgeText.textContent=k.text||q.explain||'';const facts=[...(k.facts||[])];if(q.hint)facts.push(`Hinweis: ${q.hint}`);els.knowledgeFacts.innerHTML=facts.length?`<span>${facts.join(' · ')}</span>`:'';if(els.bookmarkKnowledge){els.bookmarkKnowledge.dataset.questionId=q.id||'';els.bookmarkKnowledge.textContent='☆';els.bookmarkKnowledge.classList.remove('saved')}els.knowledgeCard.classList.remove('hidden')}
function praise(ok,q){const id=advisorFor(q);if(ok){const normal=['Prima!','Genau richtig.','Weiter so!','Bestens gelöst.','Fachlich korrekt.','Sehr gut erkannt.','Sauber gearbeitet.','Das sitzt.','Treffer – genau so.','Richtig kombiniert.','Starke Leistung.','Sehr sicher gelöst.','Passt genau.','Gut aufgepasst.','Professionell entschieden.','Ausgezeichnet gelöst.'];const repeat=['Sehr gut wiederholt.','Jetzt sitzt es.','Genau – die Wiederholung hat sich gelohnt.','Richtig, gut gefestigt.','Prima – beim zweiten Durchgang sicher gelöst.'];const pool=state.repeatMode?repeat:normal;let msg=pool[Math.floor(Math.random()*pool.length)];if(pool.length>1&&msg===state.lastPraise)msg=pool[(pool.indexOf(msg)+1)%pool.length];state.lastPraise=msg;setMentor(id,state.repeatMode?'Lernfortschritt':'Lob',msg);if(state.voice)Speech.speak(msg,{speaker:id})}else{const msg=q.explain||'Schau dir die fachliche Erklärung noch einmal an.';setMentor(id,state.repeatMode?'Noch einmal ansehen':'Kurz erklärt',msg);if(state.voice)Speech.speak(`${state.repeatMode?'Noch nicht ganz.':'Nicht ganz.'} ${msg}`,{speaker:id})}}
function ensureBonusOverlay(){let o=document.getElementById('bonusComboOverlay');if(o)return o;o=document.createElement('div');o.id='bonusComboOverlay';o.className='bonus-combo-overlay hidden';o.innerHTML=`<div class="bonus-combo-card" role="dialog" aria-modal="true" aria-labelledby="bonusComboTitle"><span class="bonus-combo-kicker">FUTURA FACH-COMBO</span><h2 id="bonusComboTitle">Zusatzfrage</h2><p id="bonusComboPrompt"></p><div id="bonusComboChoices" class="bonus-combo-choices"></div><div id="bonusComboStatus" class="bonus-combo-status"></div><div id="bonusComboActions" class="bonus-combo-actions"></div></div>`;document.body.appendChild(o);return o}
