function closeBonusCombo(){const o=document.getElementById('bonusComboOverlay');if(o)o.classList.add('hidden');state.bonusActive=false;if(!state.examActive&&['solo','prep'].includes(state.mode))els.repeatRow.classList.remove('hidden');els.next.disabled=false;els.next.textContent=state.roundIndex>=state.roundSize?'Auswertung':'Weiter';updateHUD();save()}
function bonusOffer(q,baseEarned){const o=ensureBonusOverlay(),title=o.querySelector('#bonusComboTitle'),prompt=o.querySelector('#bonusComboPrompt'),choices=o.querySelector('#bonusComboChoices'),status=o.querySelector('#bonusComboStatus'),actions=o.querySelector('#bonusComboActions');state.bonusActive=true;o.classList.remove('hidden');title.textContent='Zusatzfrage für doppelte Punktzahl?';prompt.textContent=`Du hast ${baseEarned.toLocaleString('de-DE')} Punkte sicher. Löse die Zutaten-Challenge und erhöhe diese Aufgabe auf 2×.`;choices.innerHTML='';status.textContent='Deine bisher erspielten Punkte bleiben sicher.';actions.innerHTML='<button type="button" class="secondary-btn" data-bonus-no>Punkte sichern</button><button type="button" class="primary-btn" data-bonus-yes>2× versuchen</button>';actions.querySelector('[data-bonus-no]').onclick=closeBonusCombo;actions.querySelector('[data-bonus-yes]').onclick=()=>renderBonusStage2(q,baseEarned)}
