function bonusStage3Offer(q,baseEarned){const o=ensureBonusOverlay(),title=o.querySelector('#bonusComboTitle'),prompt=o.querySelector('#bonusComboPrompt'),choices=o.querySelector('#bonusComboChoices'),status=o.querySelector('#bonusComboStatus'),actions=o.querySelector('#bonusComboActions');title.textContent='Noch eine Zusatzfrage für 3×?';prompt.textContent='Die 2×-Wertung ist sicher. Mit der Fachfrage zu Zubereitung und Garmethode kannst du diese Aufgabe auf 3× erhöhen.';choices.innerHTML='';status.textContent='Auch die doppelte Punktzahl bleibt sicher.';actions.innerHTML='<button type="button" class="secondary-btn" data-bonus-no>Punkte sichern</button><button type="button" class="primary-btn" data-bonus-yes>3× versuchen</button>';actions.querySelector('[data-bonus-no]').onclick=closeBonusCombo;actions.querySelector('[data-bonus-yes]').onclick=()=>renderBonusStage3(q,baseEarned)}
function renderBonusStage3(q,baseEarned){const stage=q.bonusCombo?.stage3,o=ensureBonusOverlay(),title=o.querySelector('#bonusComboTitle'),prompt=o.querySelector('#bonusComboPrompt'),choices=o.querySelector('#bonusComboChoices'),status=o.querySelector('#bonusComboStatus'),actions=o.querySelector('#bonusComboActions');title.textContent=stage.title||'Fachfrage · 3×';prompt.textContent=stage.prompt;status.textContent='Wähle die fachlich beste Antwort.';actions.innerHTML='';choices.innerHTML='';shuffledForQuestion(stage.choices,`${q.id}:bonus3`,x=>x[0]).forEach(opt=>{const b=document.createElement('button');b.type='button';b.className='bonus-choice bonus-scene';b.dataset.correct=opt[2]?'1':'0';b.innerHTML=`${opt[1]?`<span>${opt[1]}</span>`:''}<strong>${opt[0]}</strong>`;b.onclick=async()=>{if(choices.classList.contains('locked'))return;choices.classList.add('locked');const ok=!!opt[2];b.classList.add(ok?'correct':'wrong');if(!ok){[...choices.children].forEach((x,i)=>{const src=stage.choices.find(y=>y[0]===x.querySelector('strong')?.textContent);if(src?.[2])x.classList.add('correct')})}if(ok){state.score+=baseEarned;await logBonusAttempt(q,3,true,baseEarned);beep(true);status.textContent=`Perfekt · Aufgabe 3× gewertet · +${baseEarned.toLocaleString('de-DE')} Punkte`}else{await logBonusAttempt(q,3,false,0);beep(false);status.textContent='Nicht ganz · deine 2×-Wertung bleibt erhalten.'}actions.innerHTML='<button type="button" class="primary-btn" data-bonus-done>Weiter</button>';actions.querySelector('[data-bonus-done]').onclick=closeBonusCombo;updateHUD();save()};choices.appendChild(b)})}
