  if(isPrep){earned=ok?30:0;if(earned)state.score+=earned;if(ok)state.prepCorrect=(state.prepCorrect||0)+1;beep(ok);els.feedback.textContent=ok?`Richtig · +${earned} Lernpunkte`:'Noch unsicher · wird im Lernmodell vorgemerkt';els.feedback.className='feedback show '+(ok?'good':'bad')}else if(ok){state.correct++;earned=100*state.combo+(state.timeLimit?state.timeRemaining*2:0);state.score+=earned;state.combo=Math.min(7,state.combo+1);state.bestCombo=Math.max(state.bestCombo,state.combo);if(!state.examActive&&!isOfficialExam)state.rankXP++;beep(true);els.feedback.textContent=`Richtig · +${earned} Punkte`;els.feedback.className='feedback show good'}else{state.wrong++;state.combo=1;if(!state.examActive&&!isOfficialExam)state.rankXP=Math.max(0,state.rankXP-1);beep(false);els.feedback.textContent='Nicht ganz.';els.feedback.className='feedback show bad'}
