function updateQuickTimer(){els.quickTimerText.textContent=quickArmed?String(Math.ceil(quickSeconds)):'—';els.quickTimerFill.style.width=quickArmed?`${Math.max(0,quickSeconds/quickLimit*100)}%`:'100%';els.quickTimerFill.classList.toggle('danger',quickArmed&&quickSeconds<=15)}
