function finishPromotionExam(){const examPassed=state.examCorrect>=state.examPass,examDuration=(state.examResults||[]).reduce((a,r)=>a+(r.responseMs||0),0),profile=window.KarriereOnline?.getProfile?.()||{};window.KarriereStorage?.addSession?.({playerId:profile.id||'local',playerName:profile.name&&profile.name!=='Spieler'?profile.name:'Lokaler Spieler',sessionId:state.sessionId,sessionType:'exam',rank:state.rank,professionText:professionText(),questions:state.examTotal,correct:state.examCorrect,durationMs:examDuration,passed:examPassed});window.KarriereOnline?.syncOutbox?.();state.examActive=false;state.sessionId='';if(examPassed){if(state.rank===6)return finishCareer();const old=state.rank;state.rank++;state.rankXP=0;state.jokers=3;state.promotionReady=false;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];storeCertificate(certificateRecord(ranks[state.rank].name,{examCorrect:state.examCorrect,examTotal:state.examTotal}));const id=advisorForRank(state.rank);els.promotionMentor.src=advisors[id].image;els.promotionTitle.textContent=ranks[state.rank].name;els.promotionText.textContent=`Prüfung bestanden: ${state.examCorrect} von ${state.examTotal} richtig. Du steigst von ${ranks[old].name} zu ${ranks[state.rank].name} auf.`;els.promotionUnlock.textContent=ranks[state.rank].unlock;els.promotionStats.textContent=`Gesamt: ${state.correct} richtig · ${state.wrong} falsch · ${accuracy()} % Trefferquote`;window.KarriereOnline?.setProfile?.({rank:ranks[state.rank].name,professions:[...(state.professions||['Küche'])]});show(els.promo);if(state.voice)Speech.speak(`Glückwunsch. Du bist jetzt ${ranks[state.rank].name}.`,{speaker:id});save()}else{state.rankXP=Math.max(0,ranks[state.rank].needed-2);state.promotionReady=false;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];setMentor(advisorForRank(state.rank),'Prüfung',`Noch nicht bestanden: ${state.examCorrect} von ${state.examTotal}. Du bleibst ${ranks[state.rank].name} und kannst dich gezielt vorbereiten.`);show(els.game);nextQuestion();save()}}
function finishCareer(){storeCertificate(certificateRecord('Küchendirektor · Karriere gemeistert',{final:true,examCorrect:state.examCorrect,examTotal:state.examTotal}));els.endText.textContent=`Direktor-Challenge bestanden: ${state.examCorrect} von ${state.examTotal} richtig. Du hast die komplette Karriereleiter gemeistert.`;els.finalScore.textContent=state.score.toLocaleString('de-DE');els.finalCorrect.textContent=state.correct;els.finalCombo.textContent='x'+state.bestCombo;show(els.end);window.KarriereStorage.clearState();if(state.voice)Speech.speak('Ausgezeichnet. Du hast die Karriereleiter vollständig gemeistert.',{speaker:'sofia'})}
function hintText(q){return q.hint||'Achte auf die klassische Fachlogik und schließe unpassende Antworten aus.'}
function openAdvisor(){els.advisorCards.innerHTML='';const rec=advisorFor(state.current);Object.entries(advisors).forEach(([id,a])=>{const b=document.createElement('button');b.className='advisor-card'+(id===rec?' recommended':'');b.innerHTML=`<img src="${a.image}" alt="${a.name}"><b>${a.name}</b><small>${a.role}</small><span>${id===rec?'Empfohlen':'Fragen'}</span>`;b.onclick=()=>useJoker(id);els.advisorCards.appendChild(b)});els.advisorModal.classList.remove('hidden')}
function useJoker(id){if(state.jokers<=0||state.answered)return;state.jokers--;state.jokersUsed++;state.current._usedJoker=true;const text=hintText(state.current);setMentor(id,'Tipp',text);els.advisorModal.classList.add('hidden');updateHUD();save();if(state.voice)Speech.speak(text,{speaker:id})}
function examPreparation(){const weak=window.KarriereAdaptive?.recommendations?.(3,{professions:state.professions,maxRank:state.rank})||[];const id=advisorForRank(state.rank);const text=weak.length?`Deine persönlichen Lernschwerpunkte sind ${weak.map(x=>`${x.label}, ${x.level}`).join('; ')}. ${state.promotionReady?'Auf der Rundenauswertung kannst du fünf adaptive Übungen vor der Prüfung starten.':'Diese Themen werden in den nächsten Runden automatisch häufiger und in veränderter Form wiederholt.'}`:'Dein Lernmodell hat noch zu wenig Daten. Spiele einige weitere Aufgaben, damit ich die Vorbereitung genauer anpassen kann.';setMentor(id,'Prüfungsvorbereitung',text);if(state.voice)Speech.speak(text,{speaker:id})}
function startAdaptivePrep(){if(!state.promotionReady)return;const weak=window.KarriereAdaptive?.recommendations?.(4,{professions:state.professions,maxRank:state.rank})||[];state.mode='prep';state.prepActive=true;state.prepCorrect=0;state.prepWeakTopics=weak.map(x=>x.key);state.roundSize=5;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];state.quickPlan=[];state.quickDone=[];state.quickResults=[];beginSession('prep');show(els.game);setMentor(advisorForRank(state.rank),'Adaptive Vorbereitung',weak.length?`Wir trainieren jetzt gezielt ${weak.map(x=>x.label).join(', ')}.`:'Wir trainieren fünf passende Aufgaben vor deiner Prüfung.');nextQuestion()}
function finishAdaptivePrepAndExam(){state.mode='solo';state.prepActive=false;state.roundSize=10;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];state.quickPlan=makeQuickPlan();state.quickDone=[];state.quickResults=[];startPromotionExam()}
function pauseGame(){if(!els.game.classList.contains('active')||state.paused)return;state.paused=true;pausedStarted=performance.now();stopTimer();Speech.stop();els.pauseOverlay.classList.remove('hidden')}
function resumeGame(){if(!state.paused)return;state.paused=false;pausedMs+=performance.now()-pausedStarted;els.pauseOverlay.classList.add('hidden');resumeTimer()}

