  speak(text,{speaker='sofia',onend=null}={}){if(!text){onend?.();return}if(!state.voice){onend?.();return}this.stop();let ended=false;const done=()=>{if(ended)return;ended=true;this.setSpeaking(false);try{onend?.()}catch(e){}};const segments=this.segments(text),ext=this.findExternal();if(ext?.speak){this.setSpeaking(true,speaker);try{const r=ext.speak(text,{speaker,lang:'de-DE',segments,pronunciationLexicon,onend:done});if(r?.finally)r.finally(done);return}catch(e){}}if(!('speechSynthesis'in window)){els.speechStatus.textContent='nicht verfügbar';done();return}this.setSpeaking(true,speaker);let i=0;const next=()=>{if(i>=segments.length){done();return}const seg=segments[i++],u=new SpeechSynthesisUtterance(seg.text);u.lang=seg.lang;const voices=speechSynthesis.getVoices(),v=voices.find(x=>x.lang.toLowerCase()===seg.lang.toLowerCase())||voices.find(x=>x.lang.toLowerCase().startsWith(seg.lang.slice(0,2).toLowerCase()));if(v)u.voice=v;u.rate=speaker==='viktor'?.92:speaker==='antoine'?.96:1;u.pitch=speaker==='viktor'?.94:speaker==='sofia'?1.03:.99;u.onend=next;u.onerror=next;speechSynthesis.speak(u)};next()},
