const anatomyLabQuestions=()=>{const order=['Rind','Schwein','Lamm','Huhn'];return Q.filter(q=>q.type==='anatomy').sort((a,b)=>order.findIndex(x=>a.title.startsWith(x))-order.findIndex(x=>b.title.startsWith(x)))};
let anatomyLabMode='puzzle',anatomyLabCurrentId=null;
function openAnatomyLab(){els.anatomyLabModal.classList.remove('hidden');renderAnatomyLabSelector();const first=anatomyLabQuestions()[0];if(first)renderAnatomyLab(first.id)}
function closeAnatomyLab(){els.anatomyLabModal.classList.add('hidden')}
function renderAnatomyLabSelector(){els.anatomyLabAnimals.innerHTML='';anatomyLabQuestions().forEach(q=>{const b=document.createElement('button');b.className='anatomy-animal-btn';b.dataset.qid=q.id;const animal=/Schwein/i.test(q.title)?'🐖':/Rind/i.test(q.title)?'🐄':/Lamm/i.test(q.title)?'🐑':'🐔';b.innerHTML=`<span>${animal}</span><b>${q.title.replace(/\s*[–-].*$/,'')}</b>`;b.onclick=()=>renderAnatomyLab(q.id);els.anatomyLabAnimals.appendChild(b)})}
function setAnatomyLabMode(mode){anatomyLabMode=mode==='learn'?'learn':'puzzle';els.anatomyLearnMode.classList.toggle('active',anatomyLabMode==='learn');els.anatomyPuzzleMode.classList.toggle('active',anatomyLabMode==='puzzle');if(anatomyLabCurrentId)renderAnatomyLab(anatomyLabCurrentId,true)}
function renderAnatomyLearning(q){const parts=q.labParts||q.parts;els.anatomyLabPuzzle.innerHTML='';if(q.learnImage){const v=document.createElement('div');v.className='anatomy-learning-view professional';v.innerHTML=`<img src="${q.learnImage}" alt="${q.title} – beschriftete Fachgrafik"><div class="anatomy-learning-note"><b>Fachgrafik ansehen</b><span>Präge dir Lage und Verwendung ein. Danach auf <strong>🧩 Puzzle</strong> wechseln.</span></div>`;els.anatomyLabPuzzle.appendChild(v);els.anatomyLabStatus.textContent='Lernmodus · Beschriftete Übersicht mit Lage und Verwendung.';return}const v=document.createElement('div');v.className='anatomy-learning-view';v.innerHTML=`<div class="anatomy-learning-board"><img src="${q.labPhoto||q.photo}" alt="${q.title}">${parts.map(p=>`<span class="anatomy-learn-label" style="left:${p[2]+p[4]/2}%;top:${p[3]+p[5]/2}%">${p[0]}</span>`).join('')}</div><div class="anatomy-learning-list">${parts.map(p=>`<article><b>${p[0]}</b><small>${p[7]||'Lage am Tier einprägen.'}</small></article>`).join('')}</div>`;els.anatomyLabPuzzle.appendChild(v);els.anatomyLabStatus.textContent='Lernmodus · Lage der Teilstücke einprägen.'}
function renderAnatomyLab(id,keepMode=false){const q=Q.find(x=>x.id===id&&x.type==='anatomy');if(!q)return;anatomyLabCurrentId=id;els.anatomyLabAnimals.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.qid===id));els.anatomyLabTitle.textContent=/Schwein/i.test(q.title)?'Schwein – professionelle Teilstücke':q.title;if(!keepMode&&q.learnImage)anatomyLabMode='puzzle';els.anatomyLearnMode.classList.toggle('active',anatomyLabMode==='learn');els.anatomyPuzzleMode.classList.toggle('active',anatomyLabMode==='puzzle');if(anatomyLabMode==='learn')return renderAnatomyLearning(q);const labQ={...q,id:`${q.id}:lab`,photo:q.labPhoto||q.photo,parts:q.labParts||q.parts};els.anatomyLabStatus.textContent=`Puzzle · 0 / ${labQ.parts.length} Teilstücke eingerastet.`;buildAnatomyPuzzle(labQ,els.anatomyLabPuzzle,async(_q,stats)=>{els.anatomyLabStatus.textContent=`✓ Komplett richtig · ${stats.matched}/${labQ.parts.length} Teilstücke · ${stats.wrong} Fehlversuche.`;try{await window.KarriereAdaptive?.record?.(q,{correct:true,responseMs:stats.responseMs,usedJoker:false,repeat:false,source:'anatomy-lab'})}catch(e){}},p=>{if(p.correct){els.anatomyLabStatus.textContent=`✓ ${p.matched}/${p.total} · ${p.part}${p.usage?` · ${p.usage}`:''}`}else{els.anatomyLabStatus.textContent=`Noch nicht richtig · ${p.matched}/${p.total} eingerastet · ${p.wrong} Fehlversuche`}})}
function questionSpeech(q){let t=`${q.section?`${q.section}. `:''}${q.title}. ${q.prompt}`;if(q.type==='multi'||q.type==='plate')t+=` Antwortmöglichkeiten: ${q.choices.map(x=>x[0]).join(', ')}.`;else if(q.type==='scene')t+=` Möglichkeiten: ${q.scenes.map(x=>x[0]).join(', ')}.`;else if(q.type==='remove')t+=` Im Gericht: ${q.inside.map(x=>x[0]).join(', ')}.`;else if(q.type==='sequence')t+=` Karten: ${q.items.join(', ')}.`;else if(q.type==='match')t+=` Zuordnungen: ${q.pairs.map(x=>x[0]).join(', ')}.`;else if(q.type==='anatomy')t+=` Teilstücke: ${q.parts.map(x=>x[0]).join(', ')}.`;return t}
function speakQuestion(){if(state.current)Speech.speak(questionSpeech(state.current),{speaker:advisorFor(state.current)})}


let officialExamSelected='koch_abschluss';
function examText(q){return `${q.section||''} ${q.cat||''} ${q.title||''} ${q.examArea||''}`}
function areaForExam(profile,q){if(q.examArea){const direct=profile.areas.find(a=>q.examArea===a.name||a.name.includes(q.examArea)||q.examArea.includes(a.name));if(direct)return direct.name}const tx=examText(q);return profile.areas.find(a=>a.match.test(tx))?.name||profile.areas[0].name}
function candidatePoolForExam(profile){let pool=Q.filter(q=>(q.profession||'Küche')===profile.profession&&q.rank>=profile.minRank&&q.examEligible!==false&&(window.KarriereAdmin?.isQuestionEnabled?.(q)!==false));if(profile.id==='kuechenmeister')pool=pool.filter(q=>q.rank>=4||/Meisterprüfung|Kalkulation|Führung|Warenwirtschaft|Bankett|Recht|Rechnungswesen/i.test(examText(q)));return pool}
function buildOfficialExamIds(profile){const pool=candidatePoolForExam(profile),chosen=[];const total=profile.count,sum=profile.areas.reduce((s,x)=>s+x.weight,0);let remaining=total;profile.areas.forEach((a,i)=>{let n=i===profile.areas.length-1?remaining:Math.max(1,Math.round(total*(a.weight/sum)));n=Math.min(n,remaining);const candidates=shuffle(pool.filter(q=>areaForExam(profile,q)===a.name&&!chosen.includes(q.id)));for(const q of candidates.slice(0,n))chosen.push(q.id);remaining=total-chosen.length});if(chosen.length<total){for(const q of shuffle(pool)){if(!chosen.includes(q.id))chosen.push(q.id);if(chosen.length>=total)break}}return chosen.slice(0,total)}
function renderOfficialExamProfiles(){if(!els.examProfileGrid)return;els.examProfileGrid.innerHTML=Object.values(OFFICIAL_EXAM_PROFILES).map(p=>`<button class="exam-profile-card ${p.id===officialExamSelected?'active':''}" data-exam-profile="${p.id}"><b>${p.title}</b><span>${p.kind} · ${p.count} Lernfragen</span></button>`).join('');els.examProfileGrid.querySelectorAll('[data-exam-profile]').forEach(b=>b.onclick=()=>selectOfficialExamProfile(b.dataset.examProfile));selectOfficialExamProfile(officialExamSelected,true)}
function selectOfficialExamProfile(id,quiet=false){const p=OFFICIAL_EXAM_PROFILES[id]||OFFICIAL_EXAM_PROFILES.koch_abschluss;officialExamSelected=p.id;els.examProfileGrid?.querySelectorAll('[data-exam-profile]').forEach(b=>b.classList.toggle('active',b.dataset.examProfile===p.id));if(els.examProfileTitle)els.examProfileTitle.textContent=p.title;if(els.examAreaList)els.examAreaList.innerHTML=p.areas.map(a=>`<li><b>${a.name}</b>${p.id==='kuechenmeister'?'':' · '+a.weight+' % Lerngewichtung'}</li>`).join('');if(els.examPracticeList)els.examPracticeList.innerHTML=p.practice.map(x=>`<li>${x}</li>`).join('');if(els.examSourceNote)els.examSourceNote.textContent='Prüfungstraining mit selbst erstellten Lernfragen – keine Originalprüfungsaufgaben und keine amtliche Bestehensprognose. Vor dem echten Prüfungstermin den aktuellen Stand bei der zuständigen Kammer prüfen.';if(!quiet)Speech.stop()}

const FLASH_INTERVAL_DAYS={1:1,2:3,3:7,4:14,5:30};
let flashFilter='due',flashQueue=[],flashIndex=0,flashCurrent=null;
function flashDatePlus(days,minutes=0){return new Date(Date.now()+days*86400000+minutes*60000).toISOString()}
function flashCardFromQuestion(q,{weak=false,exam=false,reason='Fachwissen'}={}){if(!q)return null;const k=q.knowledge||{};const facts=[...(k.facts||[])];if(q.hint)facts.push(`Merksatz: ${q.hint}`);let answer=k.text||q.explain||'';if(!answer&&Array.isArray(q.answer))answer=q.answer.join(', ');return{id:`q:${q.id}`,questionId:q.id,profession:q.profession||'Küche',category:q.section||q.cat||'Fachwissen',title:q.title,front:q.prompt||q.title,backTitle:k.title||q.title,back:answer||'Siehe Fachwissen zur Aufgabe.',facts:facts.slice(0,5),image:q.photo||'',weak:!!weak,exam:!!exam||/Prüfung|WiSo|Wirtschaft|Recht|Kalkulation/i.test(`${q.section||''} ${q.cat||''}`),reason,box:1,reps:0,correctStreak:0,dueAt:new Date().toISOString()}}
async function addFlashFromQuestion(q,opts={}){const card=flashCardFromQuestion(q,opts);if(card)await window.KarriereFlashcardsStore?.upsert?.(card);return card}
async function ensureStarterFlashcards(){let cards=await window.KarriereFlashcardsStore?.list?.()||[];if(cards.length>=24)return cards;const wanted=['Salbei erkennen','Basilikum erkennen','Muskat erkennen','Ribeye / Entrecôte','Rinderfilet – klassische Zuschnitte','Garverfahren nach Bindegewebe','Sauce Hollandaise','Sauce Béarnaise','Sauce Béchamel','Was ist ein Jus?','Fischfrische','Kabeljau','Lachs','Wareneingang','Hände hygienisch waschen','Fines Herbes','Kreuzkümmel oder Kümmel?'];const starter=[];wanted.forEach(title=>{const q=Q.find(x=>x.title===title);if(q)starter.push(q)});for(const q of Q){if(starter.length>=30)break;if(q.rank<=2&&['Warenkunde','Kräuter & Gewürze','Saucenkunde','Hygiene','Fischkunde'].includes(q.cat)&&!starter.includes(q))starter.push(q)}for(const q of starter.slice(0,30))await addFlashFromQuestion(q,{exam:q.rank>=2,reason:'Starterkarte'});return window.KarriereFlashcardsStore?.list?.()||[]}
async function syncWeakFlashcards(){const attempts=await window.KarriereStorage?.allAttempts?.(300)||[];const wrongIds=[...new Set(attempts.filter(a=>a.correct===false&&!a.repeat&&a.questionId).map(a=>a.questionId))].slice(0,60);for(const id of wrongIds){const q=Q.find(x=>x.id===id);if(q)await addFlashFromQuestion(q,{weak:true,exam:state.mode==='officialExam',reason:'Falsche Antwort'})}return wrongIds.length}
function flashDue(c){return !c.dueAt||new Date(c.dueAt).getTime()<=Date.now()}
async function flashCardsFiltered(filter=flashFilter){const all=await window.KarriereFlashcardsStore?.list?.()||[];if(filter==='due')return all.filter(flashDue);if(filter==='weak')return all.filter(x=>x.weak);if(filter==='exam')return all.filter(x=>x.exam);return all}
async function updateFlashStats(){const all=await window.KarriereFlashcardsStore?.list?.()||[];els.flashDueCount.textContent=all.filter(flashDue).length;els.flashTotalCount.textContent=all.length;els.flashMasteredCount.textContent=all.filter(x=>Number(x.box)>=5).length;els.flashWeakCount.textContent=all.filter(x=>x.weak).length}
async function openFlashcards(){await ensureStarterFlashcards();await syncWeakFlashcards();flashFilter='due';document.querySelectorAll('[data-flash-filter]').forEach(b=>b.classList.toggle('active',b.dataset.flashFilter==='due'));els.flashcardsModal.classList.remove('hidden');await loadFlashQueue()}
function closeFlashcards(){els.flashcardsModal?.classList.add('hidden');Speech.stop()}
async function loadFlashQueue(){flashQueue=await flashCardsFiltered(flashFilter);flashQueue.sort((a,b)=>(new Date(a.dueAt||0)-new Date(b.dueAt||0))||((a.box||1)-(b.box||1)));flashIndex=0;await updateFlashStats();renderFlashCard()}
function renderFlashCard(){flashCurrent=flashQueue[flashIndex]||null;const empty=!flashCurrent;els.flashEmpty.classList.toggle('hidden',!empty);els.flashStudy.classList.toggle('hidden',empty);if(empty)return;const c=flashCurrent;els.flashCategory.textContent=`${c.profession||'Küche'} · ${c.category||'Fachwissen'}`;els.flashBox.textContent=`Fach ${c.box||1}`;els.flashProgress.textContent=`${flashIndex+1} / ${flashQueue.length}`;els.flashFront.textContent=c.front;els.flashBackTitle.textContent=c.backTitle||c.title;els.flashBack.textContent=c.back;els.flashFacts.innerHTML=(c.facts||[]).map(x=>`<span>${x}</span>`).join('');if(c.image){els.flashImage.src=c.image;els.flashImage.alt=c.title||'Lernkarte';els.flashImage.classList.remove('hidden')}else{els.flashImage.classList.add('hidden');els.flashImage.removeAttribute('src')}els.flashCard.classList.remove('flipped');els.flashRateRow.classList.add('hidden');els.flashHint.textContent=c.weak?'Persönliche Schwäche · diese Karte wird gezielt häufiger wiederholt.':'Leitner-System: Sichere Karten wandern in höhere Fächer.'}
function flipFlashCard(){if(!flashCurrent)return;const flipped=els.flashCard.classList.toggle('flipped');els.flashRateRow.classList.toggle('hidden',!flipped)}
async function rateFlashCard(rate){if(!flashCurrent)return;const c={...flashCurrent},box=Math.max(1,Math.min(5,Number(c.box)||1));c.reps=(c.reps||0)+1;c.lastReviewedAt=new Date().toISOString();if(rate==='again'){c.box=1;c.correctStreak=0;c.weak=true;c.dueAt=flashDatePlus(0,10)}else if(rate==='hard'){c.box=Math.max(1,box-1);c.correctStreak=0;c.weak=true;c.dueAt=flashDatePlus(1)}else if(rate==='good'){c.box=Math.min(5,box+1);c.correctStreak=(c.correctStreak||0)+1;if(c.correctStreak>=2&&c.box>=3)c.weak=false;c.dueAt=flashDatePlus(FLASH_INTERVAL_DAYS[c.box])}else{c.box=Math.min(5,box+2);c.correctStreak=(c.correctStreak||0)+2;if(c.box>=3)c.weak=false;c.dueAt=flashDatePlus(FLASH_INTERVAL_DAYS[c.box])}await window.KarriereFlashcardsStore?.upsert?.(c);flashQueue.splice(flashIndex,1);if(flashIndex>=flashQueue.length)flashIndex=Math.max(0,flashQueue.length-1);await updateFlashStats();renderFlashCard()}
function speakFlashCard(){if(!flashCurrent)return;const flipped=els.flashCard.classList.contains('flipped');Speech.speak(flipped?`${flashCurrent.backTitle}. ${flashCurrent.back}. ${(flashCurrent.facts||[]).join('. ')}`:flashCurrent.front,{speaker:advisorFor(state.current||{})})}

function openOfficialExamCenter(){officialExamSelected=state.professions?.includes('Bäckerei')?'baecker_geselle':state.professions?.includes('Konditorei')?'konditor_geselle':state.professions?.includes('Metzgerei')?'fleischer_geselle':'koch_abschluss';renderOfficialExamProfiles();els.examCenterModal?.classList.remove('hidden')}
function closeOfficialExamCenter(){els.examCenterModal?.classList.add('hidden')}
function startOfficialExamSimulation(){const p=OFFICIAL_EXAM_PROFILES[officialExamSelected];if(!p)return;state.mode='officialExam';state.officialExamProfile=p.id;state.officialExamQuestionIds=buildOfficialExamIds(p);state.officialExamAreaStats={};state.professions=[p.profession];state.roundSize=state.officialExamQuestionIds.length;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];state.quickPlan=[];state.quickDone=[];state.quickResults=[];state.used=[];beginSession('official-exam');closeOfficialExamCenter();show(els.game);nextQuestion()}
function officialExamResetToCenter(){state.mode='solo';state.officialExamProfile='';state.officialExamQuestionIds=[];state.roundSize=10;state.roundIndex=0;state.roundResults=[];openOfficialExamCenter()}

function startNew(){const prefs={sound:state.sound,voice:state.voice,autoRead:state.autoRead};const professions=selectedProfessions();state={...freshState(),...prefs,professions,quickPlan:makeQuickPlan(),quickDone:[],quickResults:[]};beginSession('round');show(els.game);updateHUD();/* Keine vorlaufende Löschung: saveState überschreibt den alten Stand atomarisch. So gibt es weder DB-Blockade noch Lösch-Race. */window.KarriereOnline?.setProfile?.({rank:ranks[state.rank].name,professions:[...professions]});nextQuestion()}
async function continueGame(){let ok=false;try{ok=await load()}catch(e){console.warn('Fortsetzen',e)}if(ok){ensureQuickPlan();setProfessionChecks(state.professions);window.KarriereOnline?.setProfile?.({rank:ranks[state.rank].name,professions:[...(state.professions||['Küche'])]});updateHUD();if(state.resumePoint==='summary'&&state.roundResults?.length){showSummary()}else{show(els.game);nextQuestion()}}else startNew()}
async function goHome(){Speech.stop();await save();await refreshStart(state);show(els.start)}
function flashLed(el){if(!el)return;el.classList.add('flash');clearTimeout(el._flashTimer);el._flashTimer=setTimeout(()=>el.classList.remove('flash'),280)}
function bindDatabaseIndicators(){const setIdb=ok=>els.idbConnLed?.classList.toggle('on',!!ok);const setSb=ok=>els.supabaseConnLed?.classList.toggle('on',!!ok);window.KarriereStorage?.on?.('status',s=>setIdb(s.ok));window.KarriereStorage?.on?.('traffic',()=>flashLed(els.idbTrafficLed));window.KarriereOnline?.on?.('status',s=>setSb(s.connected));window.KarriereOnline?.on?.('traffic',()=>flashLed(els.supabaseTrafficLed));Promise.resolve(window.KarriereStorage?.status?.()).then(s=>setIdb(s?.ok)).catch(()=>setIdb(false));setSb(window.KarriereOnline?.isConnected?.()||false)}
async function exitModule(){Speech.stop();try{clearInterval(timerHandle)}catch(e){};await save();try{window.KCFutura?.exitModule?.('karriereleiter')}catch(e){};try{if(window.parent&&window.parent!==window)window.parent.postMessage({type:'KC_FUTURA_EXIT_MODULE',module:'karriereleiter'},'*')}catch(e){};await refreshStart(state);show(els.start)}

function openOnline(){els.onlineModal.classList.remove('hidden');const p=window.KarriereOnline.getProfile();els.playerNameInput.value=p.name==='Spieler'?'':p.name;renderOnlinePlayers()}
function renderOnlinePlayers(){if(!onlinePlayers.length){els.onlinePlayers.innerHTML='<p class="empty">Aktuell ist kein anderer Spieler in der Karriereleiter-Lobby sichtbar.</p>';return}els.onlinePlayers.innerHTML='';onlinePlayers.forEach(p=>{const e=document.createElement('div');e.className='online-player';e.innerHTML=`<div><b>${p.name||'Spieler'}</b><span>${p.rank||'Karriereleiter'} · ${(p.professions||[]).map(x=>professionLabels[x]||x).join(' + ')||'online'}</span></div><button class="primary-btn compact">Challenge</button>`;e.querySelector('button').onclick=()=>challengePlayer(p);els.onlinePlayers.appendChild(e)})}
function challengeQuestionIds(){const ps=state.professions?.length?state.professions:['Küche'];const pool=shuffle(Q.filter(q=>q.challenge&&ps.includes(q.profession||'Küche')&&(window.KarriereAdmin?.isQuestionEnabled?.(q)!==false)&&q.rank>=Math.max(0,state.rank-1)&&q.rank<=state.rank));return pool.slice(0,10).map(q=>q.id)}
async function challengePlayer(p){const sent=await window.KarriereOnline.sendChallenge(p.id,challengeQuestionIds());if(sent){els.incomingChallenge.classList.remove('hidden');els.incomingChallenge.innerHTML=`Herausforderung an <b>${p.name}</b> gesendet. Die Runde startet nach Annahme.`}}
function showIncomingChallenge(c){els.incomingChallenge.classList.remove('hidden');els.incomingChallenge.innerHTML=`<b>${c.fromName}</b> fordert dich zu 10 Fragen heraus.<div class="actions"><button class="primary-btn compact" id="acceptChallenge">Annehmen</button><button class="secondary-btn compact" id="declineChallenge">Ablehnen</button></div>`;$('#acceptChallenge').onclick=async()=>{await window.KarriereOnline.respondChallenge(c,true);startDuel(c.challengeId,c.fromName,c.questionIds);els.onlineModal.classList.add('hidden')};$('#declineChallenge').onclick=async()=>{await window.KarriereOnline.respondChallenge(c,false);els.incomingChallenge.classList.add('hidden')}}
function startDuel(challengeId,name,ids){state.mode='duel';state.duelChallengeId=challengeId;state.duelOpponent=name;state.duelScore=0;state.duelOpponentScore=0;state.duelQuestionIds=ids;state.roundIndex=0;state.roundResults=[];state.roundRepeats=[];state.bonusResults=[];state.quickPlan=[];state.quickDone=[];state.quickResults=[];beginSession('duel');show(els.game);nextQuestion()}
async function setupOnline(){const p=await window.KarriereOnline.init();els.playerNameInput.value=p.name==='Spieler'?'':p.name;window.KarriereOnline.on('status',s=>{els.onlineStatusText.textContent=s.text;els.onlineStatusDot.classList.toggle('online',s.connected);els.onlineDot.classList.toggle('online',s.connected)});window.KarriereOnline.on('presence',ps=>{onlinePlayers=ps;renderOnlinePlayers()});window.KarriereOnline.on('challenge',c=>{if(c.response){if(c.accepted&&c.original)startDuel(c.challengeId,c.fromName,c.questionIds||c.original.questionIds);else if(!c.accepted){els.incomingChallenge.classList.remove('hidden');els.incomingChallenge.textContent='Die Herausforderung wurde abgelehnt.'}}else showIncomingChallenge(c)});window.KarriereOnline.on('duel',p=>{if(state.mode==='duel'&&p.challengeId===state.duelChallengeId&&p.playerId!==window.KarriereOnline.getProfile().id){state.duelOpponentScore=p.score||0;updateHUD()}})}

function init(){/* UI zuerst, alle I/O-Dienste danach und niemals blockierend. */buildStatic();Speech.draw(false);bindDatabaseIndicators();Promise.resolve(window.KarriereAdaptive?.init?.(Q)).catch(e=>console.warn('Adaptive-Lernmodell',e));Promise.resolve(window.KarriereStorage?.migrateLegacy?.()).catch(e=>console.warn('Legacy-Migration',e));Promise.resolve(window.KarriereStorage?.loadQuestionHistory?.()).then(h=>{if(Array.isArray(h))persistentQuestionHistory=h}).catch(()=>{});refreshStart(null).catch(e=>console.warn('Start-Spielstand',e));Promise.resolve(window.KarriereAdmin?.init?.()).catch(e=>console.warn('Admin-Modul',e));Promise.resolve(window.KarriereStorage?.cacheContent?.(Q,'v19.8-exam')).then(()=>window.KarriereStorage?.status?.()).then(st=>{const el=document.querySelector('.start-foot span:first-child');if(el)el.textContent=st?.ok?'IndexedDB · AES-GCM':'Fallback · AES-GCM'}).catch(e=>{const el=document.querySelector('.start-foot span:first-child');if(el)el.textContent='Fallback · AES-GCM';console.warn('Storage-Init',e)});setupOnline().catch(e=>console.warn('Online-Modul',e));window.KarriereRuntime={version:'19.8-exam',questionCount:Q.length,health:async()=>({storage:await window.KarriereStorage?.health?.(),crypto:await window.KarriereCrypto?.selfTest?.(),online:{connected:window.KarriereOnline?.isConnected?.()||false},adaptive:window.KarriereAdaptive?.selfTest?.(),questions:Q.length,professions:[...new Set(Q.map(q=>q.profession))],types:[...new Set(Q.map(q=>q.type))]}),selfTest:()=>{const required=['startScreen','startBtn','gameScreen','questionArea','nextBtn','pauseBtn','quickOverlay','exitBtn','idbConnLed','idbTrafficLed','supabaseConnLed','supabaseTrafficLed','kitchenBookModal','bookmarkKnowledgeBtn','anatomyLabModal','anatomyLabStartBtn','anatomyLearnModeBtn','anatomyPuzzleModeBtn'];const missing=required.filter(id=>!document.getElementById(id));const ids=Q.map(q=>q.id),duplicates=ids.filter((id,i)=>ids.indexOf(id)!==i);const bad=Q.filter(q=>!q.id||!q.title||!q.cat||!Number.isInteger(q.rank)||q.rank<0||q.rank>6);return{ok:!missing.length&&!duplicates.length&&!bad.length,version:'19.8-exam',missingDom:missing,duplicateQuestionIds:[...new Set(duplicates)],invalidQuestions:bad.map(q=>q.id||q.title),questions:Q.length,professions:[...new Set(Q.map(q=>q.profession))],types:[...new Set(Q.map(q=>q.type))]}}};window.KarriereRuntime.exit=exitModule;document.documentElement.dataset.karriereReady='1'}

els.flashcardsStart.onclick=openFlashcards;els.closeFlashcards.onclick=closeFlashcards;els.flashcardsModal.onclick=e=>{if(e.target===els.flashcardsModal)closeFlashcards()};els.flashCard.onclick=flipFlashCard;els.flashSpeak.onclick=speakFlashCard;els.flashSeedBtn.onclick=async()=>{await syncWeakFlashcards();await ensureStarterFlashcards();await loadFlashQueue()};document.querySelectorAll('[data-flash-filter]').forEach(b=>b.onclick=async()=>{flashFilter=b.dataset.flashFilter;document.querySelectorAll('[data-flash-filter]').forEach(x=>x.classList.toggle('active',x===b));await loadFlashQueue()});document.querySelectorAll('[data-flash-rate]').forEach(b=>b.onclick=()=>rateFlashCard(b.dataset.flashRate));
els.startBtn.onclick=startNew;els.continueBtn.onclick=continueGame;els.examCenterStart.onclick=openOfficialExamCenter;els.closeExamCenter.onclick=closeOfficialExamCenter;els.examStartSimulation.onclick=startOfficialExamSimulation;els.examCenterModal.onclick=e=>{if(e.target===els.examCenterModal)closeOfficialExamCenter()};els.kitchenBookStart.onclick=openKitchenBook;els.kitchenBookGame.onclick=openKitchenBook;els.anatomyLabStart.onclick=openAnatomyLab;els.anatomyLabGame.onclick=openAnatomyLab;els.anatomyLearnMode.onclick=()=>setAnatomyLabMode('learn');els.anatomyPuzzleMode.onclick=()=>setAnatomyLabMode('puzzle');els.closeAnatomyLab.onclick=closeAnatomyLab;els.anatomyLabModal.onclick=e=>{if(e.target===els.anatomyLabModal)closeAnatomyLab()};els.bookmarkKnowledge.onclick=rememberKnowledge;els.closeKitchenBook.onclick=closeKitchenBook;els.kitchenBookModal.onclick=e=>{if(e.target===els.kitchenBookModal)closeKitchenBook()};document.querySelectorAll('[data-book-filter]').forEach(b=>b.onclick=()=>{kitchenBookFilter=b.dataset.bookFilter;kitchenBookPage=0;document.querySelectorAll('[data-book-filter]').forEach(x=>x.classList.toggle('active',x===b));renderKitchenBook()});els.bookPrev.onclick=()=>{if(kitchenBookPage>0){kitchenBookPage--;renderKitchenBook()}};els.bookNext.onclick=()=>{kitchenBookPage++;renderKitchenBook()};els.deepDiveBtn.onclick=()=>openDeepDive();els.closeDeepDive.onclick=closeDeepDive;els.deepDiveBack.onclick=closeDeepDive;els.deepDiveModal.onclick=e=>{if(e.target===els.deepDiveModal)closeDeepDive()};els.speakDeepDive.onclick=speakDeepDive;els.quickContinue.onclick=closeQuickAndContinue;els.next.onclick=handleNext;els.repeatBtn.onclick=repeatQuestion;els.calculatorBtn.onclick=openCalculator;els.closeCalculator.onclick=closeCalculator;els.calculatorOverlay.onclick=e=>{if(e.target===els.calculatorOverlay)closeCalculator()};els.calcKeys.onclick=e=>{const b=e.target.closest('button[data-key]');if(b)calculatorInput(b.dataset.key)};els.home.onclick=goHome;els.exitBtn.onclick=exitModule;els.pauseBtn.onclick=pauseGame;els.resume.onclick=resumeGame;els.voiceBtn.onclick=()=>{state.voice=!state.voice;if(!state.voice)Speech.stop();updateHUD();save()};els.readQuestion.onclick=speakQuestion;els.autoRead.onclick=()=>{state.autoRead=!state.autoRead;updateHUD();save()};els.speakKnowledge.onclick=()=>{if(!els.knowledgeCard.classList.contains('hidden'))Speech.speak(`${els.knowledgeTitle.textContent}. ${els.knowledgeText.textContent}`,{speaker:advisorFor(state.current)})};els.advisor.onclick=openAdvisor;els.closeAdvisor.onclick=()=>els.advisorModal.classList.add('hidden');els.advisorModal.onclick=e=>{if(e.target===els.advisorModal)els.advisorModal.classList.add('hidden')};els.examPrep.onclick=examPreparation;els.summaryHome.onclick=goHome;if(els.summaryPrep)els.summaryPrep.onclick=startAdaptivePrep;els.summaryAction.onclick=()=>state.mode==='officialExam'?officialExamResetToCenter():state.mode==='prep'?finishAdaptivePrepAndExam():state.promotionReady?startPromotionExam():startNextRound();els.certificateBtn.onclick=()=>printCertificate();els.promotionBtn.onclick=()=>{show(els.game);nextQuestion()};els.finalCertificateBtn.onclick=()=>printCertificate();els.playAgain.onclick=startNew;els.endHome.onclick=()=>show(els.start);els.onlineBtn.onclick=openOnline;els.closeOnline.onclick=()=>els.onlineModal.classList.add('hidden');els.onlineModal.onclick=e=>{if(e.target===els.onlineModal)els.onlineModal.classList.add('hidden')};els.savePlayerName.onclick=async()=>{const name=els.playerNameInput.value.trim()||'Spieler';await window.KarriereOnline.setProfile({name,rank:ranks[state.rank].name,professions:[...(state.professions||['Küche'])]});await window.KarriereOnline.connect();renderOnlinePlayers()};
document.querySelectorAll('.profession-card input').forEach(cb=>cb.addEventListener('change',()=>{if(!document.querySelector('.profession-card input:checked'))cb.checked=true}));
window.addEventListener('resize',()=>Speech.draw(Speech.speaking));window.addEventListener('beforeunload',()=>save());
